    store: SessionStore,
) -> str:
    """Return a prompt template, optionally with variables filled in."""
    prompt_type = arguments["prompt_type"]
    variables = arguments.get("variables", {})

    if prompt_type not in _PROMPT_CATALOG:
        available = list(_PROMPT_CATALOG.keys())
        return json.dumps({
