class TreeSitterCppAnalyzer:
	def __init__(self, file_path: str, content: str, repo_path: str = None):
		self.file_path = Path(file_path)
		self.content = content
		self.repo_path = repo_path or ""
		self.nodes: List[Node] = []
		self.call_relationships: List[CallRelationship] = []
		self._analyze()

	def _get_module_path(self) -> str:
		if self.repo_path:
			try:
				rel_path = os.path.relpath(str(self.file_path), self.repo_path)
			except ValueError:
				rel_path = str(self.file_path)
		else:
			rel_path = str(self.file_path)

		for ext in ['.cpp', '.cc', '.cxx', '.c++', '.hpp', '.hxx', '.h++', '.h']:
			if rel_path.endswith(ext):
				rel_path = rel_path[:-len(ext)]
				break
		return rel_path.replace('/', '.').replace('\\', '.')

	def _get_relative_path(self) -> str:
		if self.repo_path:
			try:
				return os.path.relpath(str(self.file_path), self.repo_path)
			except ValueError:
				return str(self.file_path)
		else:
			return str(self.file_path)

	def _get_component_id(self, name: str, parent_class: str = None) -> str:
		rel_path = self._get_relative_path()
		if parent_class:
			return f"{rel_path}::{parent_class}.{name}"
		return f"{rel_path}::{name}"

	def _analyze(self):
		language_capsule = tree_sitter_cpp.language()
		cpp_language = Language(language_capsule)
		parser = Parser(cpp_language)
		root = self._parse_with_macro_recovery(parser)
		lines = self.content.splitlines()

		top_level_nodes = {}

		# collect all top-level nodes using recursive traversal
		self._extract_nodes(root, top_level_nodes, lines)

		# extract relationships between top-level nodes
		self._extract_relationships(root, top_level_nodes)

	def _parse_with_macro_recovery(self, parser):
		"""Parse the original source; if it has syntax errors, retry with macro
		normalization and keep whichever parse has fewer errors.

		Normalization strips ALL_CAPS tokens by naming convention, which is
		wrong for code whose *types* are ALL_CAPS (e.g. Win32 `HANDLE`/`DWORD`).
		Comparing error counts makes the heuristic self-correcting: clean files
		are never touched, and normalization is only kept when it demonstrably
		recovers structure.
		"""
		tree = parser.parse(bytes(self.content, "utf8"))
		if not tree.root_node.has_error:
			return tree.root_node

		normalized = self._normalize_for_parser(self.content)
		if normalized == self.content:
			return tree.root_node

		normalized_tree = parser.parse(bytes(normalized, "utf8"))
		if self._count_parse_errors(normalized_tree.root_node) < self._count_parse_errors(tree.root_node):
			return normalized_tree.root_node
		return tree.root_node

	def _count_parse_errors(self, root) -> int:
		errors = 0
		stack = [root]
		while stack:
			node = stack.pop()
			if node.is_error or node.is_missing:
				errors += 1
			stack.extend(node.children)
		return errors

	def _normalize_for_parser(self, content: str) -> str:
		"""Strip ALL_CAPS attribute/specifier macros that sit in front of a
		declaration so tree-sitter can recover the underlying signature. This is
		name-agnostic: it keys off the conventional ALL_CAPS macro spelling, not
		any specific library's prefix, and only fires in specifier position so
		identifiers used in expressions are preserved. Line count is unchanged so
		reported line numbers stay accurate.
		"""
		normalized_lines = []
		for line in content.splitlines():
			updated = line
			standalone = _STANDALONE_MACRO_RE.match(updated)
			if standalone and is_macro_name(standalone.group(1)):
				normalized_lines.append("")
				continue
			for pattern in (_SPECIFIER_MACRO_CALL_RE, _SPECIFIER_MACRO_RE):
				previous = None
				while previous != updated:
					previous = updated
					updated = pattern.sub(
						lambda m: (m.group(1) + m.group(3)) if is_macro_name(m.group(2)) else m.group(0),
						updated,
					)
			updated = _KEYWORD_MACRO_RE.sub(
				lambda m: (m.group(1) + m.group(2)) if is_macro_name(m.group(3)) else m.group(0),
				updated,
			)
			normalized_lines.append(updated)
		return "\n".join(normalized_lines)

	def _extract_nodes(self, node, top_level_nodes, lines):
		"""Recursively extract top-level nodes (classes, functions, global variables)."""
		node_type = None
		node_name = None
		containing_class = None

		if node.type == "class_specifier":
			# "class" + type_identifier + { ... }
			node_type = "class"
			# Find type_identifier that represents the class name
			for child in node.children:
				if child.type == "type_identifier":
					node_name = child.text.decode()
					break
		elif node.type == "struct_specifier":
			# "struct" + type_identifier + { ... }
			node_type = "struct"
			# Find type_identifier that represents the struct name
			for child in node.children:
				if child.type == "type_identifier":
					node_name = child.text.decode()
					break
		elif node.type == "function_definition":
			# Check if this is inside a class or function
			containing_class = self._find_containing_class_for_method(node)
			declarator = next((c for c in node.children if c.type == "function_declarator"), None)
			qualified_parts = self._get_qualified_declarator_parts(declarator) if declarator else []
			if not containing_class and len(qualified_parts) > 1:
				containing_class = qualified_parts[-2]
			if containing_class:
				node_type = "method"
			else:
				node_type = "function"

			if declarator:
				for child in declarator.children:
					if child.type == "identifier":
						node_name = child.text.decode()
						break
					elif child.type == "field_identifier":
						node_name = child.text.decode()
						break
					elif child.type == "qualified_identifier":
						identifiers = [c for c in child.children if c.type == "identifier"]
						if identifiers:
							node_name = identifiers[-1].text.decode()
							break
		elif node.type == "declaration":
			containing_class = self._find_containing_class_for_method(node)
			declarator = next((c for c in node.children if c.type == "function_declarator"), None)
			if containing_class and declarator:
				node_type = "method"
				node_name = self._get_declarator_name(declarator)
			elif self._is_global_variable(node):
				node_type = "variable"
				for child in node.children:
					if child.type == "init_declarator":
						identifier = next((c for c in child.children if c.type == "identifier"), None)
						if identifier:
							node_name = identifier.text.decode()
							break
					elif child.type == "identifier":
						node_name = child.text.decode()
						break
		elif node.type == "alias_declaration":
			# using name = type; — aliases are real API surface (e.g. a
			# library's public alias for an internal template), so they are
			# extracted as components and can resolve call/type references.
			node_type = "type_alias"
			for child in node.children:
				if child.type == "type_identifier":
					node_name = child.text.decode()
					break
		elif node.type == "type_definition":
			# typedef ... name; — the alias name is the trailing type_identifier
			node_type = "type_alias"
			identifiers = [c for c in node.children if c.type == "type_identifier"]
			if identifiers:
				node_name = identifiers[-1].text.decode()
		elif node.type == "namespace_definition":
			node_type = "namespace"
			found_namespace_keyword = False
			for child in node.children:
				if child.type == "namespace":
					found_namespace_keyword = True
				elif found_namespace_keyword and child.type == "identifier":
					node_name = child.text.decode()
					break

		if node_type and node_name:
			if node_type == "method":
				component_id = self._get_component_id(node_name, containing_class)
				top_level_key = component_id
			else:
				component_id = self._get_component_id(node_name)
				top_level_key = node_name

			relative_path = self._get_relative_path()

			node_obj = Node(
				id=component_id,
				name=node_name,
				component_type=node_type,
				file_path=str(self.file_path),
				relative_path=relative_path,
				source_code="\n".join(lines[node.start_point[0]:node.end_point[0]+1]),
				start_line=node.start_point[0]+1,
				end_line=node.end_point[0]+1,
				has_docstring=False,
				docstring="",
				parameters=None,
				node_type=node_type,
				base_classes=None,
				class_name=containing_class if node_type == "method" else None,
				display_name=f"{node_type} {node_name}",
				component_id=component_id,
				language="cpp",
				qualified_name=f"{containing_class}.{node_name}" if containing_class else node_name
			)

			top_level_nodes[top_level_key] = node_obj
			top_level_nodes[component_id] = node_obj
			if node_type == "method" and containing_class:
				top_level_nodes[f"{containing_class}.{node_name}"] = node_obj
				top_level_nodes.setdefault(node_name, node_obj)

			if node_type in ["class", "struct", "function", "method", "type_alias"]:
				self.nodes.append(node_obj)

		# Recursively process children
		for child in node.children:
			self._extract_nodes(child, top_level_nodes, lines)

	def _is_global_variable(self, node) -> bool:
		"""Check if a declaration node is a global variable."""
		parent = node.parent
		while parent:
			if parent.type in ["function_definition", "class_specifier", "struct_specifier"]:
				return False
			parent = parent.parent
		return True

	def _get_declarator_name(self, declarator) -> Optional[str]:
		"""Extract the declared function or method name from nested declarators."""
		for child in declarator.children:
			if child.type in ["identifier", "field_identifier"]:
				return child.text.decode()
			if child.type == "qualified_identifier":
				identifiers = [c for c in child.children if c.type in ["identifier", "field_identifier"]]
				if identifiers:
					return identifiers[-1].text.decode()
			if child.children:
				name = self._get_declarator_name(child)
				if name:
					return name
		return None

	def _get_qualified_declarator_parts(self, declarator) -> list[str]:
		if declarator is None:
			return []
		for child in declarator.children:
			if child.type == "qualified_identifier":
				return [
					c.text.decode()
					for c in child.children
					if c.type in ["identifier", "field_identifier", "type_identifier", "namespace_identifier"]
				]
			if child.children:
				parts = self._get_qualified_declarator_parts(child)
				if parts:
					return parts
		return []

	def _find_containing_class_for_method(self, node):
		"""Find the class that contains this method definition."""
		current = node.parent
		while current:
			if current.type == "class_specifier":
				# Get class name
				for child in current.children:
					if child.type == "type_identifier":
						return child.text.decode()
			elif current.type == "struct_specifier":
				# Get struct name 
				for child in current.children:
					if child.type == "type_identifier":
						return child.text.decode()
			current = current.parent
		return None

	def _extract_relationships(self, node, top_level_nodes):
		if node.type == "call_expression":
			containing_function_id = self._find_containing_function_or_method(node, top_level_nodes)
			if containing_function_id:

				# Get called function name 
				called_function = None
				receiver_name = None
				for child in node.children:
					if child.type == "identifier":
						called_function = child.text.decode()
						break
					elif child.type == "field_expression":
						receiver_name, method_name = self._get_field_call_parts(child)
						if method_name:
							called_function = method_name
							break

				if called_function:
					target_method = None
					if receiver_name:
						receiver_type = self._find_variable_type(node, receiver_name)
						if receiver_type:
							target_method = self._find_method_component(called_function, top_level_nodes, receiver_type)
					if not target_method:
						target_method = self._find_method_component(called_function, top_level_nodes)
					target_class = self._find_class_containing_method(called_function, top_level_nodes)

					if target_method:
						self.call_relationships.append(CallRelationship(
							caller=containing_function_id,
							callee=target_method,
							call_line=node.start_point[0]+1,
							is_resolved=True
						))
					elif target_class:
						target_class_id = self._get_component_id(target_class)
						self.call_relationships.append(CallRelationship(
							caller=containing_function_id,
							callee=target_class_id,
							call_line=node.start_point[0]+1,
							is_resolved=True
						))
					elif called_function in top_level_nodes:
						called_function_id = top_level_nodes[called_function].id
						self.call_relationships.append(CallRelationship(
							caller=containing_function_id,
							callee=called_function_id,
							call_line=node.start_point[0]+1,
							is_resolved=True
						))
					elif receiver_name is not None:
						# A member call whose receiver type could not be
						# resolved: a name matching an STL member here is
						# overwhelmingly likely external, so suppress it.
						if not self._is_system_function(called_function):
							self.call_relationships.append(CallRelationship(
								caller=containing_function_id,
								callee=called_function,
								call_line=node.start_point[0]+1,
								is_resolved=False
							))
					elif (
						not is_macro_name(called_function)
						and called_function not in self._find_template_parameters(node)
					):
						# Plain calls are emitted for cross-file resolution;
						# external filtering happens centrally after the
						# project resolver has had its chance.
						self.call_relationships.append(CallRelationship(
							caller=containing_function_id,
							callee=called_function,
							call_line=node.start_point[0]+1,
							is_resolved=False
						))

		elif node.type == "base_class_clause":
			# Find the containing class
			containing_class = self._find_containing_class(node)
			if containing_class:
				template_params = self._find_template_parameters(node)
				# Extract base class names
				for child in node.children:
					if child.type == "type_identifier":
						base_class = child.text.decode()
						if base_class in template_params or is_macro_name(base_class):
							continue
						containing_class_id = self._get_component_id(containing_class)
						self.call_relationships.append(CallRelationship(
							caller=containing_class_id,
							callee=base_class,
							call_line=node.start_point[0]+1,
							is_resolved=False
						))

		elif node.type == "new_expression":
			containing_function_id = self._find_containing_function_or_method(node, top_level_nodes)
			if containing_function_id:

				# Get the class being instantiated
				for child in node.children:
					if child.type == "type_identifier":
						class_name = child.text.decode()
						if class_name in top_level_nodes:
							class_id = self._get_component_id(class_name)
							self.call_relationships.append(CallRelationship(
								caller=containing_function_id,
								callee=class_id,
								call_line=node.start_point[0]+1,
								is_resolved=True
							))
						break

		elif node.type == "identifier":
			parent = node.parent
			if parent and parent.type not in ["function_definition", "class_specifier", "declaration", "function_declarator"]:
				var_name = node.text.decode()
				if var_name in top_level_nodes and top_level_nodes[var_name].component_type == "variable":
					containing_function_id = self._find_containing_function_or_method(node, top_level_nodes)
					if containing_function_id:
						self.call_relationships.append(CallRelationship(
							caller=containing_function_id,
							callee=var_name,
							call_line=node.start_point[0]+1,
							is_resolved=False
						))

		# Recursively process children
		for child in node.children:
			self._extract_relationships(child, top_level_nodes)

	def _get_field_call_parts(self, field_expression) -> tuple[Optional[str], Optional[str]]:
		receiver_name = None
		method_name = None
		for child in field_expression.children:
			if child.type == "field_identifier":
				method_name = child.text.decode()
			elif child.type == "identifier" and receiver_name is None:
				receiver_name = child.text.decode()
			elif child.type == "field_expression" and receiver_name is None:
				receiver_name = child.text.decode().split(".")[-1].split("->")[-1]
		return receiver_name, method_name

	def _find_variable_type(self, node, variable_name: str) -> Optional[str]:
		current = node.parent
		while current:
			if current.type in ["compound_statement", "field_declaration_list", "translation_unit"]:
				found = self._search_variable_declaration(current, variable_name)
				if found:
					return found
			if current.type == "function_definition":
				declarator = next((c for c in current.children if c.type == "function_declarator"), None)
				found = self._search_parameter_declaration(declarator, variable_name)
				if found:
					return found
			current = current.parent
		return None

	def _search_variable_declaration(self, node, variable_name: str) -> Optional[str]:
		for child in node.children:
			if child.type == "declaration":
				type_name = self._get_declaration_type_name(child)
				declared_name = self._get_declared_variable_name(child)
				if declared_name == variable_name:
					return type_name or self._get_constructor_type_name(child)
			if child.children and child.type not in ["class_specifier", "struct_specifier", "function_definition"]:
				found = self._search_variable_declaration(child, variable_name)
				if found:
					return found
		return None

	def _search_parameter_declaration(self, node, variable_name: str) -> Optional[str]:
		if node is None:
			return None
		if node.type == "parameter_declaration":
			type_name = self._get_declaration_type_name(node)
			declared_name = self._get_declared_variable_name(node)
			if declared_name == variable_name:
				return type_name
		for child in node.children:
			found = self._search_parameter_declaration(child, variable_name)
			if found:
				return found
		return None

	def _get_declaration_type_name(self, node) -> Optional[str]:
		for child in node.children:
			if child.type in ["type_identifier", "primitive_type", "qualified_identifier"]:
				return self._last_type_part(child.text.decode())
			if child.type in ["template_type", "generic_type"]:
				return self._last_type_part(child.text.decode().split("<", 1)[0])
		return None

	def _get_declared_variable_name(self, node) -> Optional[str]:
		for child in reversed(node.children):
			if child.type in ["identifier", "field_identifier"]:
				return child.text.decode()
			if child.type in ["init_declarator", "pointer_declarator", "reference_declarator", "array_declarator"]:
				name = self._get_declared_variable_name(child)
				if name:
					return name
		return None

	def _get_constructor_type_name(self, node) -> Optional[str]:
		for child in node.children:
			if child.type == "call_expression":
				for call_child in child.children:
					if call_child.type in ["identifier", "type_identifier"]:
						return call_child.text.decode()
			if child.children:
				found = self._get_constructor_type_name(child)
				if found:
					return found
		return None

	def _last_type_part(self, type_name: str) -> str:
		return type_name.strip("&* ").split("::")[-1]

	def _find_containing_function(self, node, top_level_nodes):
		"""Find the function that contains this node."""
		current = node.parent
		while current:
			if current.type == "function_definition":
				# Get function name
				declarator = next((c for c in current.children if c.type == "function_declarator"), None)
				if declarator:
					identifier = next((c for c in declarator.children if c.type == "identifier"), None)
					if identifier:
						func_name = identifier.text.decode()
						if func_name in top_level_nodes:
							return func_name
			current = current.parent
		return None

	def _find_containing_function_or_method(self, node, top_level_nodes):
		"""Find the function or method that contains this node."""
		current = node.parent
		while current:
			if current.type == "function_definition":
				declarator = next((c for c in current.children if c.type == "function_declarator"), None)
				if declarator:
					func_name = self._get_declarator_name(declarator)
					if func_name:
						containing_class = self._find_containing_class_for_method(current)
						qualified_parts = self._get_qualified_declarator_parts(declarator)
						if not containing_class and len(qualified_parts) > 1:
							containing_class = qualified_parts[-2]
						if containing_class:
							return self._get_component_id(func_name, containing_class)
						return self._get_component_id(func_name)
			current = current.parent
		return None

	def _get_component_id_for_function(self, func_name, top_level_nodes):
		if func_name in top_level_nodes:
			node_obj = top_level_nodes[func_name]
			if hasattr(node_obj, 'class_name') and node_obj.class_name:
				return self._get_component_id(func_name, node_obj.class_name)
			else:
				return self._get_component_id(func_name)
		return self._get_component_id(func_name)

	def _find_containing_class(self, node):
		"""Find the class that contains this node."""
		current = node.parent
		while current:
			if current.type == "class_specifier":
				# Get class name
				for child in current.children:
					if child.type == "type_identifier":
						return child.text.decode()
			current = current.parent
		return None

	def _find_template_parameters(self, node) -> set:
		"""Collect template type-parameter names in scope at this node, so a
		reference to `T`/`Char`/... is not reported as an unresolved project
		symbol."""
		params = set()
		current = node.parent
		while current:
			if current.type == "template_declaration":
				param_list = next(
					(c for c in current.children if c.type == "template_parameter_list"), None
				)
				if param_list:
					for param in param_list.children:
						for child in getattr(param, "children", []):
							if child.type == "type_identifier":
								params.add(child.text.decode())
			current = current.parent
		return params

	def _is_system_function(self, func_name: str) -> bool:
		"""Check if a call target is external rather than a project function.

		Besides the curated standard-library set, an ALL_CAPS callee is treated as
		a macro invocation: macros are not extracted as components, so a call to
		one can never resolve to a project function and would otherwise pollute the
		graph as unresolved noise. This only affects the unresolved fallback —
		real components in ALL_CAPS (rare in C++) are matched by the earlier
		resolution branches before this check runs.
		"""
		if is_external_symbol("cpp", func_name):
			return True
		return is_macro_name(func_name)

	def _find_method_component(self, method_name, top_level_nodes, class_name: str = None):
		if class_name:
			qualified_key = f"{class_name}.{method_name}"
			if qualified_key in top_level_nodes:
				return top_level_nodes[qualified_key].id
		for node_obj in top_level_nodes.values():
			if node_obj.component_type == "method" and node_obj.name == method_name:
				return node_obj.id
		return None

	def _find_class_containing_method(self, method_name, top_level_nodes):
		for node_name, node_obj in top_level_nodes.items():
			if node_obj.component_type in ["class", "struct"]:
				if self._class_has_method(node_obj, method_name):
					return node_name
		return None

	def _class_has_method(self, class_node, method_name):
		lines = class_node.source_code.split('\n')
		for line in lines:
			if f'{method_name}(' in line and ('void' in line or 'int' in line or 'bool' in line or class_node.name in line):
				return True
		return False

def _get_module_path(self) -> str:
	if self.repo_path:
		try:
			rel_path = os.path.relpath(str(self.file_path), self.repo_path)
		except ValueError:
			rel_path = str(self.file_path)
	else:
		rel_path = str(self.file_path)

	for ext in ['.cpp', '.cc', '.cxx', '.c++', '.hpp', '.hxx', '.h++', '.h']:
		if rel_path.endswith(ext):
			rel_path = rel_path[:-len(ext)]
			break
	return rel_path.replace('/', '.').replace('\\', '.')

def _get_relative_path(self) -> str:
	if self.repo_path:
		try:
			return os.path.relpath(str(self.file_path), self.repo_path)
		except ValueError:
			return str(self.file_path)
	else:
		return str(self.file_path)

def _get_component_id(self, name: str, parent_class: str = None) -> str:
	rel_path = self._get_relative_path()
	if parent_class:
		return f"{rel_path}::{parent_class}.{name}"
	return f"{rel_path}::{name}"

def _count_parse_errors(self, root) -> int:
	errors = 0
	stack = [root]
	while stack:
		node = stack.pop()
		if node.is_error or node.is_missing:
			errors += 1
		stack.extend(node.children)
	return errors

def _extract_nodes(self, node, top_level_nodes, lines):
	"""Recursively extract top-level nodes (classes, functions, global variables)."""
	node_type = None
	node_name = None
	containing_class = None

	if node.type == "class_specifier":
		# "class" + type_identifier + { ... }
		node_type = "class"
		# Find type_identifier that represents the class name
		for child in node.children:
			if child.type == "type_identifier":
				node_name = child.text.decode()
				break
	elif node.type == "struct_specifier":
		# "struct" + type_identifier + { ... }
		node_type = "struct"
		# Find type_identifier that represents the struct name
		for child in node.children:
			if child.type == "type_identifier":
				node_name = child.text.decode()
				break
	elif node.type == "function_definition":
		# Check if this is inside a class or function
		containing_class = self._find_containing_class_for_method(node)
		declarator = next((c for c in node.children if c.type == "function_declarator"), None)
		qualified_parts = self._get_qualified_declarator_parts(declarator) if declarator else []
		if not containing_class and len(qualified_parts) > 1:
			containing_class = qualified_parts[-2]
		if containing_class:
			node_type = "method"
		else:
			node_type = "function"

		if declarator:
			for child in declarator.children:
				if child.type == "identifier":
					node_name = child.text.decode()
					break
				elif child.type == "field_identifier":
					node_name = child.text.decode()
					break
				elif child.type == "qualified_identifier":
					identifiers = [c for c in child.children if c.type == "identifier"]
					if identifiers:
						node_name = identifiers[-1].text.decode()
						break
	elif node.type == "declaration":
		containing_class = self._find_containing_class_for_method(node)
		declarator = next((c for c in node.children if c.type == "function_declarator"), None)
		if containing_class and declarator:
			node_type = "method"
			node_name = self._get_declarator_name(declarator)
		elif self._is_global_variable(node):
			node_type = "variable"
			for child in node.children:
				if child.type == "init_declarator":
					identifier = next((c for c in child.children if c.type == "identifier"), None)
					if identifier:
						node_name = identifier.text.decode()
						break
				elif child.type == "identifier":
					node_name = child.text.decode()
					break
	elif node.type == "alias_declaration":
		# using name = type; — aliases are real API surface (e.g. a
		# library's public alias for an internal template), so they are
		# extracted as components and can resolve call/type references.
		node_type = "type_alias"
		for child in node.children:
			if child.type == "type_identifier":
				node_name = child.text.decode()
				break
	elif node.type == "type_definition":
		# typedef ... name; — the alias name is the trailing type_identifier
		node_type = "type_alias"
		identifiers = [c for c in node.children if c.type == "type_identifier"]
		if identifiers:
			node_name = identifiers[-1].text.decode()
	elif node.type == "namespace_definition":
		node_type = "namespace"
		found_namespace_keyword = False
		for child in node.children:
			if child.type == "namespace":
				found_namespace_keyword = True
			elif found_namespace_keyword and child.type == "identifier":
				node_name = child.text.decode()
				break

	if node_type and node_name:
		if node_type == "method":
			component_id = self._get_component_id(node_name, containing_class)
			top_level_key = component_id
		else:
			component_id = self._get_component_id(node_name)
			top_level_key = node_name

		relative_path = self._get_relative_path()

		node_obj = Node(
			id=component_id,
			name=node_name,
			component_type=node_type,
			file_path=str(self.file_path),
			relative_path=relative_path,
			source_code="\n".join(lines[node.start_point[0]:node.end_point[0]+1]),
			start_line=node.start_point[0]+1,
			end_line=node.end_point[0]+1,
			has_docstring=False,
			docstring="",
			parameters=None,
			node_type=node_type,
			base_classes=None,
			class_name=containing_class if node_type == "method" else None,
			display_name=f"{node_type} {node_name}",
			component_id=component_id,
			language="cpp",
			qualified_name=f"{containing_class}.{node_name}" if containing_class else node_name
		)

		top_level_nodes[top_level_key] = node_obj
		top_level_nodes[component_id] = node_obj
		if node_type == "method" and containing_class:
			top_level_nodes[f"{containing_class}.{node_name}"] = node_obj
			top_level_nodes.setdefault(node_name, node_obj)

		if node_type in ["class", "struct", "function", "method", "type_alias"]:
			self.nodes.append(node_obj)

	# Recursively process children
	for child in node.children:
		self._extract_nodes(child, top_level_nodes, lines)

def _is_global_variable(self, node) -> bool:
	"""Check if a declaration node is a global variable."""
	parent = node.parent
	while parent:
		if parent.type in ["function_definition", "class_specifier", "struct_specifier"]:
			return False
		parent = parent.parent
	return True

def _get_declarator_name(self, declarator) -> Optional[str]:
	"""Extract the declared function or method name from nested declarators."""
	for child in declarator.children:
		if child.type in ["identifier", "field_identifier"]:
			return child.text.decode()
		if child.type == "qualified_identifier":
			identifiers = [c for c in child.children if c.type in ["identifier", "field_identifier"]]
			if identifiers:
				return identifiers[-1].text.decode()
		if child.children:
			name = self._get_declarator_name(child)
			if name:
				return name
	return None

def _get_qualified_declarator_parts(self, declarator) -> list[str]:
	if declarator is None:
		return []
	for child in declarator.children:
		if child.type == "qualified_identifier":
			return [
				c.text.decode()
				for c in child.children
				if c.type in ["identifier", "field_identifier", "type_identifier", "namespace_identifier"]
			]
		if child.children:
			parts = self._get_qualified_declarator_parts(child)
			if parts:
				return parts
	return []

def _find_containing_class_for_method(self, node):
	"""Find the class that contains this method definition."""
	current = node.parent
	while current:
		if current.type == "class_specifier":
			# Get class name
			for child in current.children:
				if child.type == "type_identifier":
					return child.text.decode()
		elif current.type == "struct_specifier":
			# Get struct name 
			for child in current.children:
				if child.type == "type_identifier":
					return child.text.decode()
		current = current.parent
	return None

def _extract_relationships(self, node, top_level_nodes):
	if node.type == "call_expression":
		containing_function_id = self._find_containing_function_or_method(node, top_level_nodes)
		if containing_function_id:

			# Get called function name 
			called_function = None
			receiver_name = None
			for child in node.children:
				if child.type == "identifier":
					called_function = child.text.decode()
					break
				elif child.type == "field_expression":
					receiver_name, method_name = self._get_field_call_parts(child)
					if method_name:
						called_function = method_name
						break

			if called_function:
				target_method = None
				if receiver_name:
					receiver_type = self._find_variable_type(node, receiver_name)
					if receiver_type:
						target_method = self._find_method_component(called_function, top_level_nodes, receiver_type)
				if not target_method:
					target_method = self._find_method_component(called_function, top_level_nodes)
				target_class = self._find_class_containing_method(called_function, top_level_nodes)

				if target_method:
					self.call_relationships.append(CallRelationship(
						caller=containing_function_id,
						callee=target_method,
						call_line=node.start_point[0]+1,
						is_resolved=True
					))
				elif target_class:
					target_class_id = self._get_component_id(target_class)
					self.call_relationships.append(CallRelationship(
						caller=containing_function_id,
						callee=target_class_id,
						call_line=node.start_point[0]+1,
						is_resolved=True
					))
				elif called_function in top_level_nodes:
					called_function_id = top_level_nodes[called_function].id
					self.call_relationships.append(CallRelationship(
						caller=containing_function_id,
						callee=called_function_id,
						call_line=node.start_point[0]+1,
						is_resolved=True
					))
				elif receiver_name is not None:
					# A member call whose receiver type could not be
					# resolved: a name matching an STL member here is
					# overwhelmingly likely external, so suppress it.
					if not self._is_system_function(called_function):
						self.call_relationships.append(CallRelationship(
							caller=containing_function_id,
							callee=called_function,
							call_line=node.start_point[0]+1,
							is_resolved=False
						))
				elif (
					not is_macro_name(called_function)
					and called_function not in self._find_template_parameters(node)
				):
					# Plain calls are emitted for cross-file resolution;
					# external filtering happens centrally after the
					# project resolver has had its chance.
					self.call_relationships.append(CallRelationship(
						caller=containing_function_id,
						callee=called_function,
						call_line=node.start_point[0]+1,
						is_resolved=False
					))

	elif node.type == "base_class_clause":
		# Find the containing class
		containing_class = self._find_containing_class(node)
		if containing_class:
			template_params = self._find_template_parameters(node)
			# Extract base class names
			for child in node.children:
				if child.type == "type_identifier":
					base_class = child.text.decode()
					if base_class in template_params or is_macro_name(base_class):
						continue
					containing_class_id = self._get_component_id(containing_class)
					self.call_relationships.append(CallRelationship(
						caller=containing_class_id,
						callee=base_class,
						call_line=node.start_point[0]+1,
						is_resolved=False
					))

	elif node.type == "new_expression":
		containing_function_id = self._find_containing_function_or_method(node, top_level_nodes)
		if containing_function_id:

			# Get the class being instantiated
			for child in node.children:
				if child.type == "type_identifier":
					class_name = child.text.decode()
					if class_name in top_level_nodes:
						class_id = self._get_component_id(class_name)
						self.call_relationships.append(CallRelationship(
							caller=containing_function_id,
							callee=class_id,
							call_line=node.start_point[0]+1,
							is_resolved=True
						))
					break

	elif node.type == "identifier":
		parent = node.parent
		if parent and parent.type not in ["function_definition", "class_specifier", "declaration", "function_declarator"]:
			var_name = node.text.decode()
			if var_name in top_level_nodes and top_level_nodes[var_name].component_type == "variable":
				containing_function_id = self._find_containing_function_or_method(node, top_level_nodes)
				if containing_function_id:
					self.call_relationships.append(CallRelationship(
						caller=containing_function_id,
						callee=var_name,
						call_line=node.start_point[0]+1,
						is_resolved=False
					))

	# Recursively process children
	for child in node.children:
		self._extract_relationships(child, top_level_nodes)

def _get_field_call_parts(self, field_expression) -> tuple[Optional[str], Optional[str]]:
	receiver_name = None
	method_name = None
	for child in field_expression.children:
		if child.type == "field_identifier":
			method_name = child.text.decode()
		elif child.type == "identifier" and receiver_name is None:
			receiver_name = child.text.decode()
		elif child.type == "field_expression" and receiver_name is None:
			receiver_name = child.text.decode().split(".")[-1].split("->")[-1]
	return receiver_name, method_name

def _find_variable_type(self, node, variable_name: str) -> Optional[str]:
	current = node.parent
	while current:
		if current.type in ["compound_statement", "field_declaration_list", "translation_unit"]:
			found = self._search_variable_declaration(current, variable_name)
			if found:
				return found
		if current.type == "function_definition":
			declarator = next((c for c in current.children if c.type == "function_declarator"), None)
			found = self._search_parameter_declaration(declarator, variable_name)
			if found:
				return found
		current = current.parent
	return None

def _search_variable_declaration(self, node, variable_name: str) -> Optional[str]:
	for child in node.children:
		if child.type == "declaration":
			type_name = self._get_declaration_type_name(child)
			declared_name = self._get_declared_variable_name(child)
			if declared_name == variable_name:
				return type_name or self._get_constructor_type_name(child)
		if child.children and child.type not in ["class_specifier", "struct_specifier", "function_definition"]:
			found = self._search_variable_declaration(child, variable_name)
			if found:
				return found
	return None

def _search_parameter_declaration(self, node, variable_name: str) -> Optional[str]:
	if node is None:
		return None
	if node.type == "parameter_declaration":
		type_name = self._get_declaration_type_name(node)
		declared_name = self._get_declared_variable_name(node)
		if declared_name == variable_name:
			return type_name
	for child in node.children:
		found = self._search_parameter_declaration(child, variable_name)
		if found:
			return found
	return None

def _get_declaration_type_name(self, node) -> Optional[str]:
	for child in node.children:
		if child.type in ["type_identifier", "primitive_type", "qualified_identifier"]:
			return self._last_type_part(child.text.decode())
		if child.type in ["template_type", "generic_type"]:
			return self._last_type_part(child.text.decode().split("<", 1)[0])
	return None

def _get_declared_variable_name(self, node) -> Optional[str]:
	for child in reversed(node.children):
		if child.type in ["identifier", "field_identifier"]:
			return child.text.decode()
		if child.type in ["init_declarator", "pointer_declarator", "reference_declarator", "array_declarator"]:
			name = self._get_declared_variable_name(child)
			if name:
				return name
	return None

def _get_constructor_type_name(self, node) -> Optional[str]:
	for child in node.children:
		if child.type == "call_expression":
			for call_child in child.children:
				if call_child.type in ["identifier", "type_identifier"]:
					return call_child.text.decode()
		if child.children:
			found = self._get_constructor_type_name(child)
			if found:
				return found
	return None

def _find_containing_function(self, node, top_level_nodes):
	"""Find the function that contains this node."""
	current = node.parent
	while current:
		if current.type == "function_definition":
			# Get function name
			declarator = next((c for c in current.children if c.type == "function_declarator"), None)
			if declarator:
				identifier = next((c for c in declarator.children if c.type == "identifier"), None)
				if identifier:
					func_name = identifier.text.decode()
					if func_name in top_level_nodes:
						return func_name
		current = current.parent
	return None

def _find_containing_function_or_method(self, node, top_level_nodes):
	"""Find the function or method that contains this node."""
	current = node.parent
	while current:
		if current.type == "function_definition":
			declarator = next((c for c in current.children if c.type == "function_declarator"), None)
			if declarator:
				func_name = self._get_declarator_name(declarator)
				if func_name:
					containing_class = self._find_containing_class_for_method(current)
					qualified_parts = self._get_qualified_declarator_parts(declarator)
					if not containing_class and len(qualified_parts) > 1:
						containing_class = qualified_parts[-2]
					if containing_class:
						return self._get_component_id(func_name, containing_class)
					return self._get_component_id(func_name)
		current = current.parent
	return None

def _get_component_id_for_function(self, func_name, top_level_nodes):
	if func_name in top_level_nodes:
		node_obj = top_level_nodes[func_name]
		if hasattr(node_obj, 'class_name') and node_obj.class_name:
			return self._get_component_id(func_name, node_obj.class_name)
		else:
			return self._get_component_id(func_name)
	return self._get_component_id(func_name)

def _find_containing_class(self, node):
	"""Find the class that contains this node."""
	current = node.parent
	while current:
		if current.type == "class_specifier":
			# Get class name
			for child in current.children:
				if child.type == "type_identifier":
					return child.text.decode()
		current = current.parent
	return None

def _find_template_parameters(self, node) -> set:
	"""Collect template type-parameter names in scope at this node, so a
	reference to `T`/`Char`/... is not reported as an unresolved project
	symbol."""
	params = set()
	current = node.parent
	while current:
		if current.type == "template_declaration":
			param_list = next(
				(c for c in current.children if c.type == "template_parameter_list"), None
			)
			if param_list:
				for param in param_list.children:
					for child in getattr(param, "children", []):
						if child.type == "type_identifier":
							params.add(child.text.decode())
		current = current.parent
	return params

def _find_method_component(self, method_name, top_level_nodes, class_name: str = None):
	if class_name:
		qualified_key = f"{class_name}.{method_name}"
		if qualified_key in top_level_nodes:
			return top_level_nodes[qualified_key].id
	for node_obj in top_level_nodes.values():
		if node_obj.component_type == "method" and node_obj.name == method_name:
			return node_obj.id
	return None

def _find_class_containing_method(self, method_name, top_level_nodes):
	for node_name, node_obj in top_level_nodes.items():
		if node_obj.component_type in ["class", "struct"]:
			if self._class_has_method(node_obj, method_name):
				return node_name
	return None

def _class_has_method(self, class_node, method_name):
	lines = class_node.source_code.split('\n')
	for line in lines:
		if f'{method_name}(' in line and ('void' in line or 'int' in line or 'bool' in line or class_node.name in line):
			return True
	return False

def analyze_cpp_file(file_path: str, content: str, repo_path: str = None) -> Tuple[List[Node], List[CallRelationship]]:
	analyzer = TreeSitterCppAnalyzer(file_path, content, repo_path)
	return analyzer.nodes, analyzer.call_relationships

class TreeSitterCSharpAnalyzer:
    def __init__(self, file_path: str, content: str, repo_path: str = None):
        self.file_path = Path(file_path)
        self.content = content
        self.repo_path = repo_path or ""
        self.nodes: List[Node] = []
        self.call_relationships: List[CallRelationship] = []
        self.alias_map: dict[str, str] = {}
        self.using_namespaces: list[str] = []
        self.static_usings: list[str] = []
        self.file_scoped_namespace: str = ""
        self._analyze()

    def _get_relative_path(self) -> str:
        if self.repo_path:
            try:
                return os.path.relpath(str(self.file_path), self.repo_path)
            except ValueError:
                return str(self.file_path)
        return str(self.file_path)

    def _get_component_id(self, name: str) -> str:
        return f"{self._get_relative_path()}::{name}"

    def _analyze(self):
        language_capsule = tree_sitter_c_sharp.language()
        cs_language = Language(language_capsule)
        parser = Parser(cs_language)
        tree = parser.parse(bytes(self.content, "utf8"))
        root = tree.root_node
        lines = self.content.splitlines()

        self._extract_usings(root)

        top_level_nodes = {}
        self._extract_nodes(root, top_level_nodes, lines)
        self._extract_relationships(root, top_level_nodes)

    # ------------------------------------------------------------------ usings

    def _extract_usings(self, node):
        """Collect ``using`` directives (plain / alias / static) and the
        file-scoped namespace via an AST walk — directives can sit inside block
        namespaces and come in several forms that a regex would miss."""
        if node.type == "file_scoped_namespace_declaration":
            name_node = node.child_by_field_name("name")
            if name_node:
                self.file_scoped_namespace = name_node.text.decode()
        elif node.type == "using_directive":
            children = [c for c in node.children if c.type not in ("using", ";", "global")]
            has_static = any(c.type == "static" for c in node.children)
            has_alias = any(c.type == "=" for c in node.children)
            name_children = [c for c in children if c.type in ("identifier", "qualified_name")]
            if has_alias and len(name_children) >= 2:
                self.alias_map[name_children[0].text.decode()] = name_children[1].text.decode()
            elif has_static and name_children:
                self.static_usings.append(name_children[-1].text.decode())
            elif name_children:
                self.using_namespaces.append(name_children[-1].text.decode())

        for child in node.children:
            self._extract_usings(child)

    # ------------------------------------------------------------- namespaces

    def _namespace_for(self, node) -> str:
        """The namespace in scope at ``node``: the file-scoped namespace (if
        any) followed by every enclosing block ``namespace_declaration``."""
        parts = []
        current = node
        while current:
            if current.type == "namespace_declaration":
                name_node = current.child_by_field_name("name")
                if name_node:
                    parts.append(name_node.text.decode())
            current = current.parent
        parts.reverse()
        if self.file_scoped_namespace:
            parts.insert(0, self.file_scoped_namespace)
        return ".".join(p for p in parts if p)

    def _qualify(self, node, *names) -> str:
        ns = self._namespace_for(node)
        parts = [ns] if ns else []
        parts.extend(n for n in names if n)
        return ".".join(parts)

    # ------------------------------------------------------------------ nodes

    def _extract_nodes(self, node, top_level_nodes, lines):
        node_type = None
        node_name = None
        qualified_name = None
        class_name = None

        if node.type == "class_declaration":
            is_abstract = any(c.type == "modifier" and c.text.decode() == "abstract" for c in node.children)
            is_static = any(c.type == "modifier" and c.text.decode() == "static" for c in node.children)
            node_type = "static class" if is_static else ("abstract class" if is_abstract else "class")
            node_name = self._decl_name(node)
            qualified_name = self._qualify(node, *self._find_containing_type_names(node), node_name)
        elif node.type == "interface_declaration":
            node_type = "interface"
            node_name = self._decl_name(node)
            qualified_name = self._qualify(node, *self._find_containing_type_names(node), node_name)
        elif node.type == "struct_declaration":
            node_type = "struct"
            node_name = self._decl_name(node)
            qualified_name = self._qualify(node, *self._find_containing_type_names(node), node_name)
        elif node.type == "enum_declaration":
            node_type = "enum"
            node_name = self._decl_name(node)
            qualified_name = self._qualify(node, *self._find_containing_type_names(node), node_name)
        elif node.type == "record_declaration":
            is_struct = any(c.type == "struct" for c in node.children)
            node_type = "record struct" if is_struct else "record"
            node_name = self._decl_name(node)
            qualified_name = self._qualify(node, *self._find_containing_type_names(node), node_name)
        elif node.type == "delegate_declaration":
            node_type = "delegate"
            node_name = self._decl_name(node)
            qualified_name = self._qualify(node, *self._find_containing_type_names(node), node_name)
        elif node.type == "method_declaration":
            method_name = self._decl_name(node)
            if method_name:
                node_type = "method"
                containing_types = self._find_containing_type_names(node)
                if containing_types:
                    class_name = containing_types[-1]
                    node_name = f"{class_name}.{method_name}"
                    qualified_name = self._qualify(node, *containing_types, method_name)
                else:
                    node_name = method_name
                    qualified_name = self._qualify(node, method_name)

        if node_type and node_name:
            component_id = self._get_component_id(node_name)
            has_docstring, docstring = self._extract_doc_comment(node)
            node_obj = Node(
                id=component_id,
                name=node_name,
                component_type=node_type,
                file_path=str(self.file_path),
                relative_path=self._get_relative_path(),
                source_code="\n".join(lines[node.start_point[0]:node.end_point[0]+1]),
                start_line=node.start_point[0]+1,
                end_line=node.end_point[0]+1,
                has_docstring=has_docstring,
                docstring=docstring,
                parameters=None,
                node_type=node_type,
                base_classes=None,
                class_name=class_name,
                display_name=f"{node_type} {node_name}",
                component_id=component_id,
                language="csharp",
                qualified_name=qualified_name,
            )
            self.nodes.append(node_obj)
            top_level_nodes[node_name] = node_obj
            top_level_nodes[component_id] = node_obj
            if qualified_name:
                top_level_nodes[qualified_name] = node_obj
                top_level_nodes.setdefault(qualified_name.split(".")[-1], node_obj)

        for child in node.children:
            self._extract_nodes(child, top_level_nodes, lines)

    def _extract_doc_comment(self, node) -> Tuple[bool, str]:
        """Collect a ``///`` XML doc-comment block immediately preceding the
        declaration (skipping any attribute lists between comment and decl)."""
        comments = []
        sib = node.prev_sibling
        while sib is not None:
            if sib.type == "attribute_list":
                sib = sib.prev_sibling
                continue
            if sib.type == "comment" and sib.text.decode().lstrip().startswith("///"):
                comments.append(sib.text.decode())
                sib = sib.prev_sibling
                continue
            break
        if not comments:
            return False, ""
        comments.reverse()
        cleaned = []
        for c in comments:
            stripped = c.strip()
            if stripped.startswith("///"):
                stripped = stripped[3:].strip()
            cleaned.append(stripped)
        return True, "\n".join(cleaned)

    # ---------------------------------------------------------- relationships

    def _extract_relationships(self, node, top_level_nodes):
        # 1. Base list — extends and/or implements (C# does not distinguish).
        if node.type in _TYPE_DECLS:
            decl_name = self._decl_name(node)
            base_list = next((c for c in node.children if c.type == "base_list"), None)
            if decl_name and base_list:
                caller_id = self._get_component_id(decl_name)
                for base_type in self._base_list_types(base_list):
                    if not self._skip_type(base_type, node):
                        self.call_relationships.append(CallRelationship(
                            caller=caller_id,
                            callee=self._resolve_cs_type(base_type, node, top_level_nodes),
                            call_line=node.start_point[0]+1,
                            is_resolved=False,
                        ))

        # 2. Field / property / event type use + primary-constructor params.
        if node.type == "field_declaration":
            self._emit_type_use(self._variable_declaration_type(node), node, top_level_nodes)
        elif node.type == "event_field_declaration":
            self._emit_type_use(self._variable_declaration_type(node), node, top_level_nodes)
        elif node.type == "property_declaration":
            self._emit_type_use(node.child_by_field_name("type"), node, top_level_nodes)
        elif node.type in ("class_declaration", "struct_declaration", "record_declaration"):
            # Primary constructor parameters (C# 12 / records).
            param_list = next((c for c in node.children if c.type == "parameter_list"), None)
            if param_list:
                for param in param_list.children:
                    if param.type == "parameter":
                        self._emit_type_use(param.child_by_field_name("type"), node, top_level_nodes)

        # 3. Method / function invocations.
        if node.type == "invocation_expression":
            self._handle_invocation(node, top_level_nodes)

        # 4. Object creation.
        if node.type == "object_creation_expression":
            containing_class = self._find_containing_class(node, top_level_nodes)
            type_node = node.child_by_field_name("type")
            if containing_class and type_node:
                created_type = self._unwrap_type(type_node)
                if created_type and not self._skip_type(created_type, node):
                    self.call_relationships.append(CallRelationship(
                        caller=containing_class,
                        callee=self._resolve_cs_type(created_type, node, top_level_nodes),
                        call_line=node.start_point[0]+1,
                        is_resolved=False,
                    ))

        for child in node.children:
            self._extract_relationships(child, top_level_nodes)

    def _emit_type_use(self, type_node, context_node, top_level_nodes):
        if type_node is None:
            return
        containing_class = self._find_containing_class(context_node, top_level_nodes)
        if not containing_class:
            return
        type_name = self._unwrap_type(type_node)
        if type_name and not self._skip_type(type_name, context_node):
            self.call_relationships.append(CallRelationship(
                caller=containing_class,
                callee=self._resolve_cs_type(type_name, context_node, top_level_nodes),
                call_line=context_node.start_point[0]+1,
                is_resolved=False,
            ))

    def _handle_invocation(self, node, top_level_nodes):
        containing_class = self._find_containing_class(node, top_level_nodes)
        if not containing_class:
            return
        caller_id = self._find_containing_method(node) or containing_class

        func = node.child_by_field_name("function")
        if func is None:
            return

        method_name = None
        target_type = None
        bare = False

        if func.type == "identifier":
            method_name = func.text.decode()
            bare = True
        elif func.type == "member_access_expression":
            name_node = func.child_by_field_name("name")
            if name_node is None or name_node.type != "identifier":
                return
            method_name = name_node.text.decode()
            expr = func.child_by_field_name("expression")
            if expr is None:
                return
            if expr.type == "this_expression":
                bare = True
            elif expr.type == "base_expression":
                target_type = self._first_base_type(node)
                if target_type is None:
                    bare = True
            elif expr.type == "identifier":
                receiver = expr.text.decode()
                target_type = self._find_variable_type(node, receiver)
                if not target_type and receiver in top_level_nodes:
                    target_type = receiver
                if not target_type and receiver[:1].isupper() and not receiver.isupper():
                    # PascalCase receiver with no matching variable reads as a
                    # static call on a type from another file or a using; an
                    # ALL_CAPS receiver is a constant, not a type.
                    target_type = receiver
            else:
                # Chained / qualified receiver (a.B().C(), Outer.Inner.M()).
                return
        else:
            return

        if method_name in (None, "nameof"):
            return

        if bare:
            # A local / inherited member of an enclosing type (same-file nodes
            # match here; cross-file ones resolve later by simple/tail name).
            for candidate in self._enclosing_member_candidates(node, method_name):
                if candidate in top_level_nodes:
                    self._add_edge(caller_id, candidate, node)
                    return
            # Otherwise it may be a statically-imported member. We cannot know
            # which `using static` it came from, so emit one candidate per static
            # class: the right one resolves cross-file, framework guesses
            # (System.*) are filtered downstream, and a member that exists in no
            # static class simply stays an honest unresolved gap.
            for static_using in self.static_usings:
                self._add_edge(caller_id, f"{static_using}.{method_name}", node)
            return

        if target_type and not self._skip_type(target_type, node):
            callee = self._resolve_cs_member(method_name, node, top_level_nodes, target_type)
            if callee not in top_level_nodes and method_name in CSHARP_OBJECT_METHODS:
                # Inherited System.Object method the project type does not
                # override locally — never a project edge.
                return
            self._add_edge(caller_id, callee, node)

    def _add_edge(self, caller, callee, node):
        self.call_relationships.append(CallRelationship(
            caller=caller,
            callee=callee,
            call_line=node.start_point[0]+1,
            is_resolved=False,
        ))

    def _enclosing_member_candidates(self, node, member_name):
        containing_types = self._find_containing_type_names(node)
        return [
            self._qualify(node, *containing_types[:idx], member_name)
            for idx in range(len(containing_types), 0, -1)
        ]

    # ------------------------------------------------------------ type helpers

    def _base_list_types(self, base_list):
        types = []
        for child in base_list.children:
            if child.type in ("identifier", "qualified_name", "generic_name"):
                name = self._unwrap_type(child)
                if name:
                    types.append(name)
            elif child.type == "primary_constructor_base_type":
                inner = next(
                    (c for c in child.children if c.type in ("identifier", "qualified_name", "generic_name")),
                    None,
                )
                name = self._unwrap_type(inner) if inner else None
                if name:
                    types.append(name)
        return types

    def _first_base_type(self, node):
        """First base type of the type enclosing ``node`` (for ``base.X()``)."""
        current = node.parent
        while current:
            if current.type in _TYPE_DECLS:
                base_list = next((c for c in current.children if c.type == "base_list"), None)
                if base_list:
                    bases = self._base_list_types(base_list)
                    return bases[0] if bases else None
                return None
            current = current.parent
        return None

    def _variable_declaration_type(self, node):
        vd = next((c for c in node.children if c.type == "variable_declaration"), None)
        if vd is None:
            return None
        return self._first_type_child(vd)

    def _first_type_child(self, node):
        return next(
            (c for c in node.children if c.type in _TYPE_NODES or c.type == "implicit_type"),
            None,
        )

    def _unwrap_type(self, node) -> Optional[str]:
        if node is None:
            return None
        if node.type in ("identifier", "qualified_name", "predefined_type"):
            return node.text.decode()
        if node.type == "generic_name":
            ident = next((c for c in node.children if c.type == "identifier"), None)
            return ident.text.decode() if ident else None
        if node.type in ("nullable_type", "array_type", "pointer_type"):
            inner = node.child_by_field_name("type")
            if inner is None:
                inner = next((c for c in node.children if c.type in _TYPE_NODES), None)
            return self._unwrap_type(inner)
        return None

    def _simple_type_name(self, type_name: str) -> str:
        return type_name.strip().split("<", 1)[0].strip()

    def _skip_type(self, type_name: str, context_node) -> bool:
        """Types that can *never* be a project component: language primitives and
        generic type parameters in scope.

        Framework types (``List``, ``Console``, ``Task``...) are deliberately NOT
        filtered here. Doing so at extraction time would drop a real edge whenever
        a project type shadows a framework name (`resolve first, filter second`,
        per the parser audit). Their references are emitted unresolved and the
        cross-file resolver gets first chance; only the still-unresolved ones are
        classified external downstream in ``_is_external_callee``. Alias targets
        are likewise left to ``_resolve_cs_type``, which expands the alias to its
        fully-qualified form so a `using S = System.X;` reference filters
        downstream by its real namespace."""
        if not type_name:
            return True
        simple = self._simple_type_name(type_name)
        if simple in _CSHARP_PRIMITIVES:
            return True
        return simple in self._find_type_parameters(context_node)

    def _find_type_parameters(self, node) -> set:
        params = set()
        current = node
        while current:
            if current.type in (*_TYPE_DECLS, "delegate_declaration", "method_declaration", "local_function_statement"):
                type_params = next((c for c in current.children if c.type == "type_parameter_list"), None)
                if type_params:
                    for param in type_params.children:
                        if param.type == "type_parameter":
                            ident = next((c for c in param.children if c.type == "identifier"), None)
                            if ident:
                                params.add(ident.text.decode())
            current = current.parent
        return params

    def _resolve_cs_type(self, type_name: str, context_node, top_level_nodes) -> str:
        if not type_name:
            return type_name
        simple = self._simple_type_name(type_name)
        if "." in simple:
            return simple
        if simple in self.alias_map:
            return self.alias_map[simple]
        containing_types = self._find_containing_type_names(context_node)
        for idx in range(len(containing_types), 0, -1):
            candidate = self._qualify(context_node, *containing_types[:idx], simple)
            if candidate in top_level_nodes:
                return candidate
        # A `using MyApp.Models;` makes a type in that namespace reachable by its
        # simple name; prefer a known project node there over a bare guess.
        for namespace in self.using_namespaces:
            candidate = f"{namespace}.{simple}"
            if candidate in top_level_nodes:
                return candidate
        # Unlike Java, C# has no per-type imports, so the real namespace of an
        # unresolved simple type is unknown. Returning the bare name (rather than
        # fabricating the file's own namespace) lets a genuine project type still
        # match cross-file by its simple/tail name, while a third-party type used
        # via `using SomeLib;` stays unqualified — so the resolver's
        # namespace-origin rule can classify `SomeLib.Type.method`-style edges as
        # external instead of mistaking the fabricated namespace for the project.
        return simple

    def _resolve_cs_member(self, member_name, context_node, top_level_nodes, target_type) -> str:
        """Resolve a member call on a known receiver type to a `Type.member`
        candidate the cross-file resolver can match."""
        qualified_type = self._resolve_cs_type(target_type, context_node, top_level_nodes)
        candidate = f"{qualified_type}.{member_name}"
        if candidate in top_level_nodes:
            return candidate
        simple_candidate = f"{qualified_type.split('.')[-1]}.{member_name}"
        if simple_candidate in top_level_nodes:
            return simple_candidate
        return candidate

    # ----------------------------------------------------------- scope lookup

    def _decl_name(self, node) -> Optional[str]:
        name_node = node.child_by_field_name("name")
        return name_node.text.decode() if name_node else None

    def _find_containing_class(self, node, top_level_nodes):
        current = node.parent
        while current:
            if current.type in _TYPE_DECLS:
                class_name = self._decl_name(current)
                if class_name and class_name in top_level_nodes:
                    return self._get_component_id(class_name)
            current = current.parent
        return None

    def _find_containing_class_name(self, node):
        names = self._find_containing_type_names(node)
        return names[-1] if names else None

    def _find_containing_type_names(self, node) -> list:
        names = []
        current = node.parent
        while current:
            if current.type in _TYPE_DECLS:
                name = self._decl_name(current)
                if name:
                    names.append(name)
            current = current.parent
        return list(reversed(names))

    def _find_containing_method(self, node):
        current = node.parent
        while current:
            if current.type == "method_declaration":
                method_name = self._decl_name(current)
                class_name = self._find_containing_class_name(current)
                if method_name and class_name:
                    return self._get_component_id(f"{class_name}.{method_name}")
            current = current.parent
        return None

    def _find_variable_type(self, node, variable_name):
        # Method / constructor / local-function scope: parameters and locals.
        method_node = node.parent
        while method_node and method_node.type not in (
            "method_declaration", "constructor_declaration", "local_function_statement"
        ):
            method_node = method_node.parent

        if method_node:
            param_list = next((c for c in method_node.children if c.type == "parameter_list"), None)
            param_type = self._param_type(param_list, variable_name)
            if param_type:
                return param_type
            body = next((c for c in method_node.children if c.type == "block"), None)
            if body:
                local_type = self._search_variable_declaration(body, variable_name)
                if local_type:
                    return local_type

        # Class scope: primary-constructor params, fields, and properties.
        class_node = node.parent
        while class_node and class_node.type not in _TYPE_DECLS:
            class_node = class_node.parent

        if class_node:
            param_list = next((c for c in class_node.children if c.type == "parameter_list"), None)
            param_type = self._param_type(param_list, variable_name)
            if param_type:
                return param_type
            body = next((c for c in class_node.children if c.type == "declaration_list"), None)
            if body:
                for member in body.children:
                    if member.type in ("field_declaration", "event_field_declaration"):
                        vd = next((c for c in member.children if c.type == "variable_declaration"), None)
                        if vd and self._declares_variable(vd, variable_name):
                            return self._unwrap_type(self._first_type_child(vd))
                    elif member.type == "property_declaration":
                        name_node = member.child_by_field_name("name")
                        if name_node and name_node.text.decode() == variable_name:
                            return self._unwrap_type(member.child_by_field_name("type"))
        return None

    def _param_type(self, param_list, variable_name):
        if param_list is None:
            return None
        for param in param_list.children:
            if param.type == "parameter":
                name_node = param.child_by_field_name("name")
                type_node = param.child_by_field_name("type")
                if name_node and type_node and name_node.text.decode() == variable_name:
                    return self._unwrap_type(type_node)
        return None

    def _declares_variable(self, variable_declaration, variable_name) -> bool:
        for child in variable_declaration.children:
            if child.type == "variable_declarator":
                ident = next((c for c in child.children if c.type == "identifier"), None)
                if ident and ident.text.decode() == variable_name:
                    return True
        return False

    def _search_variable_declaration(self, block_node, variable_name):
        for child in block_node.children:
            if child.type == "local_declaration_statement":
                vd = next((c for c in child.children if c.type == "variable_declaration"), None)
                if vd is None:
                    continue
                type_node = self._first_type_child(vd)
                for decl in vd.children:
                    if decl.type != "variable_declarator":
                        continue
                    ident = next((c for c in decl.children if c.type == "identifier"), None)
                    if not (ident and ident.text.decode() == variable_name):
                        continue
                    if type_node is not None and type_node.type != "implicit_type":
                        return self._unwrap_type(type_node)
                    # `var` — recover the type only from a `new T()` initializer.
                    init = next((c for c in decl.children if c.type == "object_creation_expression"), None)
                    if init is not None:
                        return self._unwrap_type(init.child_by_field_name("type"))
                    return None
            elif child.type in (
                "block", "if_statement", "else_clause", "for_statement",
                "foreach_statement", "while_statement", "do_statement",
                "using_statement", "try_statement", "catch_clause",
                "finally_clause", "switch_statement", "lock_statement",
                "switch_section",
            ):
                result = self._search_variable_declaration(child, variable_name)
                if result:
                    return result
        return None

def _get_relative_path(self) -> str:
    if self.repo_path:
        try:
            return os.path.relpath(str(self.file_path), self.repo_path)
        except ValueError:
            return str(self.file_path)
    return str(self.file_path)

def _extract_usings(self, node):
    """Collect ``using`` directives (plain / alias / static) and the
    file-scoped namespace via an AST walk — directives can sit inside block
    namespaces and come in several forms that a regex would miss."""
    if node.type == "file_scoped_namespace_declaration":
        name_node = node.child_by_field_name("name")
        if name_node:
            self.file_scoped_namespace = name_node.text.decode()
    elif node.type == "using_directive":
        children = [c for c in node.children if c.type not in ("using", ";", "global")]
        has_static = any(c.type == "static" for c in node.children)
        has_alias = any(c.type == "=" for c in node.children)
        name_children = [c for c in children if c.type in ("identifier", "qualified_name")]
        if has_alias and len(name_children) >= 2:
            self.alias_map[name_children[0].text.decode()] = name_children[1].text.decode()
        elif has_static and name_children:
            self.static_usings.append(name_children[-1].text.decode())
        elif name_children:
            self.using_namespaces.append(name_children[-1].text.decode())

    for child in node.children:
        self._extract_usings(child)

def _namespace_for(self, node) -> str:
    """The namespace in scope at ``node``: the file-scoped namespace (if
    any) followed by every enclosing block ``namespace_declaration``."""
    parts = []
    current = node
    while current:
        if current.type == "namespace_declaration":
            name_node = current.child_by_field_name("name")
            if name_node:
                parts.append(name_node.text.decode())
        current = current.parent
    parts.reverse()
    if self.file_scoped_namespace:
        parts.insert(0, self.file_scoped_namespace)
    return ".".join(p for p in parts if p)

def _qualify(self, node, *names) -> str:
    ns = self._namespace_for(node)
    parts = [ns] if ns else []
    parts.extend(n for n in names if n)
    return ".".join(parts)

def _extract_doc_comment(self, node) -> Tuple[bool, str]:
    """Collect a ``///`` XML doc-comment block immediately preceding the
    declaration (skipping any attribute lists between comment and decl)."""
    comments = []
    sib = node.prev_sibling
    while sib is not None:
        if sib.type == "attribute_list":
            sib = sib.prev_sibling
            continue
        if sib.type == "comment" and sib.text.decode().lstrip().startswith("///"):
            comments.append(sib.text.decode())
            sib = sib.prev_sibling
            continue
        break
    if not comments:
        return False, ""
    comments.reverse()
    cleaned = []
    for c in comments:
        stripped = c.strip()
        if stripped.startswith("///"):
            stripped = stripped[3:].strip()
        cleaned.append(stripped)
    return True, "\n".join(cleaned)

def _extract_relationships(self, node, top_level_nodes):
    # 1. Base list — extends and/or implements (C# does not distinguish).
    if node.type in _TYPE_DECLS:
        decl_name = self._decl_name(node)
        base_list = next((c for c in node.children if c.type == "base_list"), None)
        if decl_name and base_list:
            caller_id = self._get_component_id(decl_name)
            for base_type in self._base_list_types(base_list):
                if not self._skip_type(base_type, node):
                    self.call_relationships.append(CallRelationship(
                        caller=caller_id,
                        callee=self._resolve_cs_type(base_type, node, top_level_nodes),
                        call_line=node.start_point[0]+1,
                        is_resolved=False,
                    ))

    # 2. Field / property / event type use + primary-constructor params.
    if node.type == "field_declaration":
        self._emit_type_use(self._variable_declaration_type(node), node, top_level_nodes)
    elif node.type == "event_field_declaration":
        self._emit_type_use(self._variable_declaration_type(node), node, top_level_nodes)
    elif node.type == "property_declaration":
        self._emit_type_use(node.child_by_field_name("type"), node, top_level_nodes)
    elif node.type in ("class_declaration", "struct_declaration", "record_declaration"):
        # Primary constructor parameters (C# 12 / records).
        param_list = next((c for c in node.children if c.type == "parameter_list"), None)
        if param_list:
            for param in param_list.children:
                if param.type == "parameter":
                    self._emit_type_use(param.child_by_field_name("type"), node, top_level_nodes)

    # 3. Method / function invocations.
    if node.type == "invocation_expression":
        self._handle_invocation(node, top_level_nodes)

    # 4. Object creation.
    if node.type == "object_creation_expression":
        containing_class = self._find_containing_class(node, top_level_nodes)
        type_node = node.child_by_field_name("type")
        if containing_class and type_node:
            created_type = self._unwrap_type(type_node)
            if created_type and not self._skip_type(created_type, node):
                self.call_relationships.append(CallRelationship(
                    caller=containing_class,
                    callee=self._resolve_cs_type(created_type, node, top_level_nodes),
                    call_line=node.start_point[0]+1,
                    is_resolved=False,
                ))

    for child in node.children:
        self._extract_relationships(child, top_level_nodes)

def _emit_type_use(self, type_node, context_node, top_level_nodes):
    if type_node is None:
        return
    containing_class = self._find_containing_class(context_node, top_level_nodes)
    if not containing_class:
        return
    type_name = self._unwrap_type(type_node)
    if type_name and not self._skip_type(type_name, context_node):
        self.call_relationships.append(CallRelationship(
            caller=containing_class,
            callee=self._resolve_cs_type(type_name, context_node, top_level_nodes),
            call_line=context_node.start_point[0]+1,
            is_resolved=False,
        ))

def _handle_invocation(self, node, top_level_nodes):
    containing_class = self._find_containing_class(node, top_level_nodes)
    if not containing_class:
        return
    caller_id = self._find_containing_method(node) or containing_class

    func = node.child_by_field_name("function")
    if func is None:
        return

    method_name = None
    target_type = None
    bare = False

    if func.type == "identifier":
        method_name = func.text.decode()
        bare = True
    elif func.type == "member_access_expression":
        name_node = func.child_by_field_name("name")
        if name_node is None or name_node.type != "identifier":
            return
        method_name = name_node.text.decode()
        expr = func.child_by_field_name("expression")
        if expr is None:
            return
        if expr.type == "this_expression":
            bare = True
        elif expr.type == "base_expression":
            target_type = self._first_base_type(node)
            if target_type is None:
                bare = True
        elif expr.type == "identifier":
            receiver = expr.text.decode()
            target_type = self._find_variable_type(node, receiver)
            if not target_type and receiver in top_level_nodes:
                target_type = receiver
            if not target_type and receiver[:1].isupper() and not receiver.isupper():
                # PascalCase receiver with no matching variable reads as a
                # static call on a type from another file or a using; an
                # ALL_CAPS receiver is a constant, not a type.
                target_type = receiver
        else:
            # Chained / qualified receiver (a.B().C(), Outer.Inner.M()).
            return
    else:
        return

    if method_name in (None, "nameof"):
        return

    if bare:
        # A local / inherited member of an enclosing type (same-file nodes
        # match here; cross-file ones resolve later by simple/tail name).
        for candidate in self._enclosing_member_candidates(node, method_name):
            if candidate in top_level_nodes:
                self._add_edge(caller_id, candidate, node)
                return
        # Otherwise it may be a statically-imported member. We cannot know
        # which `using static` it came from, so emit one candidate per static
        # class: the right one resolves cross-file, framework guesses
        # (System.*) are filtered downstream, and a member that exists in no
        # static class simply stays an honest unresolved gap.
        for static_using in self.static_usings:
            self._add_edge(caller_id, f"{static_using}.{method_name}", node)
        return

    if target_type and not self._skip_type(target_type, node):
        callee = self._resolve_cs_member(method_name, node, top_level_nodes, target_type)
        if callee not in top_level_nodes and method_name in CSHARP_OBJECT_METHODS:
            # Inherited System.Object method the project type does not
            # override locally — never a project edge.
            return
        self._add_edge(caller_id, callee, node)

def _enclosing_member_candidates(self, node, member_name):
    containing_types = self._find_containing_type_names(node)
    return [
        self._qualify(node, *containing_types[:idx], member_name)
        for idx in range(len(containing_types), 0, -1)
    ]

def _base_list_types(self, base_list):
    types = []
    for child in base_list.children:
        if child.type in ("identifier", "qualified_name", "generic_name"):
            name = self._unwrap_type(child)
            if name:
                types.append(name)
        elif child.type == "primary_constructor_base_type":
            inner = next(
                (c for c in child.children if c.type in ("identifier", "qualified_name", "generic_name")),
                None,
            )
            name = self._unwrap_type(inner) if inner else None
            if name:
                types.append(name)
    return types

def _first_base_type(self, node):
    """First base type of the type enclosing ``node`` (for ``base.X()``)."""
    current = node.parent
    while current:
        if current.type in _TYPE_DECLS:
            base_list = next((c for c in current.children if c.type == "base_list"), None)
            if base_list:
                bases = self._base_list_types(base_list)
                return bases[0] if bases else None
            return None
        current = current.parent
    return None

def _variable_declaration_type(self, node):
    vd = next((c for c in node.children if c.type == "variable_declaration"), None)
    if vd is None:
        return None
    return self._first_type_child(vd)

def _first_type_child(self, node):
    return next(
        (c for c in node.children if c.type in _TYPE_NODES or c.type == "implicit_type"),
        None,
    )

def _unwrap_type(self, node) -> Optional[str]:
    if node is None:
        return None
    if node.type in ("identifier", "qualified_name", "predefined_type"):
        return node.text.decode()
    if node.type == "generic_name":
        ident = next((c for c in node.children if c.type == "identifier"), None)
        return ident.text.decode() if ident else None
    if node.type in ("nullable_type", "array_type", "pointer_type"):
        inner = node.child_by_field_name("type")
        if inner is None:
            inner = next((c for c in node.children if c.type in _TYPE_NODES), None)
        return self._unwrap_type(inner)
    return None

def _find_type_parameters(self, node) -> set:
    params = set()
    current = node
    while current:
        if current.type in (*_TYPE_DECLS, "delegate_declaration", "method_declaration", "local_function_statement"):
            type_params = next((c for c in current.children if c.type == "type_parameter_list"), None)
            if type_params:
                for param in type_params.children:
                    if param.type == "type_parameter":
                        ident = next((c for c in param.children if c.type == "identifier"), None)
                        if ident:
                            params.add(ident.text.decode())
        current = current.parent
    return params

def _decl_name(self, node) -> Optional[str]:
    name_node = node.child_by_field_name("name")
    return name_node.text.decode() if name_node else None

def _find_containing_class(self, node, top_level_nodes):
    current = node.parent
    while current:
        if current.type in _TYPE_DECLS:
            class_name = self._decl_name(current)
            if class_name and class_name in top_level_nodes:
                return self._get_component_id(class_name)
        current = current.parent
    return None

def _find_containing_class_name(self, node):
    names = self._find_containing_type_names(node)
    return names[-1] if names else None

def _find_containing_type_names(self, node) -> list:
    names = []
    current = node.parent
    while current:
        if current.type in _TYPE_DECLS:
            name = self._decl_name(current)
            if name:
                names.append(name)
        current = current.parent
    return list(reversed(names))

def _find_containing_method(self, node):
    current = node.parent
    while current:
        if current.type == "method_declaration":
            method_name = self._decl_name(current)
            class_name = self._find_containing_class_name(current)
            if method_name and class_name:
                return self._get_component_id(f"{class_name}.{method_name}")
        current = current.parent
    return None

def _find_variable_type(self, node, variable_name):
    # Method / constructor / local-function scope: parameters and locals.
    method_node = node.parent
    while method_node and method_node.type not in (
        "method_declaration", "constructor_declaration", "local_function_statement"
    ):
        method_node = method_node.parent

    if method_node:
        param_list = next((c for c in method_node.children if c.type == "parameter_list"), None)
        param_type = self._param_type(param_list, variable_name)
        if param_type:
            return param_type
        body = next((c for c in method_node.children if c.type == "block"), None)
        if body:
            local_type = self._search_variable_declaration(body, variable_name)
            if local_type:
                return local_type

    # Class scope: primary-constructor params, fields, and properties.
    class_node = node.parent
    while class_node and class_node.type not in _TYPE_DECLS:
        class_node = class_node.parent

    if class_node:
        param_list = next((c for c in class_node.children if c.type == "parameter_list"), None)
        param_type = self._param_type(param_list, variable_name)
        if param_type:
            return param_type
        body = next((c for c in class_node.children if c.type == "declaration_list"), None)
        if body:
            for member in body.children:
                if member.type in ("field_declaration", "event_field_declaration"):
                    vd = next((c for c in member.children if c.type == "variable_declaration"), None)
                    if vd and self._declares_variable(vd, variable_name):
                        return self._unwrap_type(self._first_type_child(vd))
                elif member.type == "property_declaration":
                    name_node = member.child_by_field_name("name")
                    if name_node and name_node.text.decode() == variable_name:
                        return self._unwrap_type(member.child_by_field_name("type"))
    return None

def _param_type(self, param_list, variable_name):
    if param_list is None:
        return None
    for param in param_list.children:
        if param.type == "parameter":
            name_node = param.child_by_field_name("name")
            type_node = param.child_by_field_name("type")
            if name_node and type_node and name_node.text.decode() == variable_name:
                return self._unwrap_type(type_node)
    return None

def _declares_variable(self, variable_declaration, variable_name) -> bool:
    for child in variable_declaration.children:
        if child.type == "variable_declarator":
            ident = next((c for c in child.children if c.type == "identifier"), None)
            if ident and ident.text.decode() == variable_name:
                return True
    return False

def _search_variable_declaration(self, block_node, variable_name):
    for child in block_node.children:
        if child.type == "local_declaration_statement":
            vd = next((c for c in child.children if c.type == "variable_declaration"), None)
            if vd is None:
                continue
            type_node = self._first_type_child(vd)
            for decl in vd.children:
                if decl.type != "variable_declarator":
                    continue
                ident = next((c for c in decl.children if c.type == "identifier"), None)
                if not (ident and ident.text.decode() == variable_name):
                    continue
                if type_node is not None and type_node.type != "implicit_type":
                    return self._unwrap_type(type_node)
                # `var` — recover the type only from a `new T()` initializer.
                init = next((c for c in decl.children if c.type == "object_creation_expression"), None)
                if init is not None:
                    return self._unwrap_type(init.child_by_field_name("type"))
                return None
        elif child.type in (
            "block", "if_statement", "else_clause", "for_statement",
            "foreach_statement", "while_statement", "do_statement",
            "using_statement", "try_statement", "catch_clause",
            "finally_clause", "switch_statement", "lock_statement",
            "switch_section",
        ):
            result = self._search_variable_declaration(child, variable_name)
            if result:
                return result
    return None

def analyze_csharp_file(file_path: str, content: str, repo_path: str = None) -> Tuple[List[Node], List[CallRelationship]]:
    analyzer = TreeSitterCSharpAnalyzer(file_path, content, repo_path)
    return analyzer.nodes, analyzer.call_relationships

class TreeSitterJavaAnalyzer:
	def __init__(self, file_path: str, content: str, repo_path: str = None):
		self.file_path = Path(file_path)
		self.content = content
		self.repo_path = repo_path or ""
		self.nodes: List[Node] = []
		self.call_relationships: List[CallRelationship] = []
		self.package_name = self._extract_package_name()
		self.import_map, self.wildcard_imports = self._extract_imports()
		self._analyze()

	def _get_module_path(self) -> str:
		if self.repo_path:
			try:
				rel_path = os.path.relpath(str(self.file_path), self.repo_path)
			except ValueError:
				rel_path = str(self.file_path)
		else:
			rel_path = str(self.file_path)

		for ext in ['.java']:
			if rel_path.endswith(ext):
				rel_path = rel_path[:-len(ext)]
				break
		return rel_path.replace('/', '.').replace('\\', '.')

	def _get_relative_path(self) -> str:
		"""Get relative path from repo root."""
		if self.repo_path:
			try:
				return os.path.relpath(str(self.file_path), self.repo_path)
			except ValueError:
				return str(self.file_path)
		else:
			return str(self.file_path)

	def _get_component_id(self, name: str, parent_class: str = None) -> str:
		rel_path = self._get_relative_path()
		if parent_class:
			return f"{rel_path}::{parent_class}.{name}"
		else:
			return f"{rel_path}::{name}"

	def _extract_package_name(self) -> str:
		match = re.search(r"^\s*package\s+([\w.]+)\s*;", self.content, re.MULTILINE)
		return match.group(1) if match else ""

	def _extract_imports(self) -> tuple[dict[str, str], list[str]]:
		import_map: dict[str, str] = {}
		wildcards: list[str] = []
		for match in re.finditer(r"^\s*import\s+(?:static\s+)?([\w.]+)(\.\*)?\s*;", self.content, re.MULTILINE):
			import_name = match.group(1)
			if match.group(2):
				wildcards.append(import_name)
			else:
				import_map[import_name.rsplit(".", 1)[-1]] = import_name
		return import_map, wildcards

	def _analyze(self):
		language_capsule = tree_sitter_java.language()
		java_language = Language(language_capsule)
		parser = Parser(java_language)
		tree = parser.parse(bytes(self.content, "utf8"))
		root = tree.root_node
		lines = self.content.splitlines()

		top_level_nodes = {}

		self._extract_nodes(root, top_level_nodes, lines)

		self._extract_relationships(root, top_level_nodes)

	def _extract_nodes(self, node, top_level_nodes, lines):
		node_type = None
		node_name = None
		qualified_name = None
		class_name = None

		if node.type == "class_declaration":
			is_abstract = any(c.type == "modifier" and c.text.decode() == "abstract" for c in node.children)
			node_type = "abstract class" if is_abstract else "class"
			name_node = next((c for c in node.children if c.type == "identifier"), None)
			node_name = name_node.text.decode() if name_node else None
			qualified_name = self._qualified_type_name(node_name, self._find_containing_type_names(node))
		elif node.type == "interface_declaration":
			node_type = "interface"
			name_node = next((c for c in node.children if c.type == "identifier"), None)
			node_name = name_node.text.decode() if name_node else None
			qualified_name = self._qualified_type_name(node_name, self._find_containing_type_names(node))
		elif node.type == "enum_declaration":
			node_type = "enum"
			name_node = next((c for c in node.children if c.type == "identifier"), None)
			node_name = name_node.text.decode() if name_node else None
			qualified_name = self._qualified_type_name(node_name, self._find_containing_type_names(node))
		elif node.type == "record_declaration":
			node_type = "record"
			name_node = next((c for c in node.children if c.type == "identifier"), None)
			node_name = name_node.text.decode() if name_node else None
			qualified_name = self._qualified_type_name(node_name, self._find_containing_type_names(node))
		elif node.type == "annotation_type_declaration":
			node_type = "annotation"
			name_node = next((c for c in node.children if c.type == "identifier"), None)
			node_name = name_node.text.decode() if name_node else None
			qualified_name = self._qualified_type_name(node_name, self._find_containing_type_names(node))
		elif node.type == "method_declaration":
			node_type = "method"
			name_node = next((c for c in node.children if c.type == "identifier"), None)
			if name_node:
				method_name = name_node.text.decode()
				containing_types = self._find_containing_type_names(node)
				if containing_types:
					class_name = containing_types[-1]
					node_name = f"{class_name}.{method_name}"
					qualified_name = self._qualified_member_name(containing_types, method_name)
				else:
					node_name = method_name
					qualified_name = self._qualify_name(method_name)

		if node_type and node_name:
			component_id = self._get_component_id(node_name)
			relative_path = self._get_relative_path()
			node_obj = Node(
				id=component_id,
				name=node_name,
				component_type=node_type,
				file_path=str(self.file_path),
				relative_path=relative_path,
				source_code="\n".join(lines[node.start_point[0]:node.end_point[0]+1]),
				start_line=node.start_point[0]+1,
				end_line=node.end_point[0]+1,
				has_docstring=False,
				docstring="",
				parameters=None,
				node_type=node_type,
				base_classes=None,
				class_name=class_name,
				display_name=f"{node_type} {node_name}",
				component_id=component_id,
				language="java",
				qualified_name=qualified_name
			)
			self.nodes.append(node_obj)
			top_level_nodes[node_name] = node_obj
			top_level_nodes[component_id] = node_obj
			if qualified_name:
				top_level_nodes[qualified_name] = node_obj
				top_level_nodes.setdefault(qualified_name.split(".")[-1], node_obj)

		# Recursively process children
		for child in node.children:
			self._extract_nodes(child, top_level_nodes, lines)

	def _extract_relationships(self, node, top_level_nodes):
		# 1. Inheritance: Class extends another class
		if node.type == "class_declaration":
			class_name = self._get_identifier_name(node)
			children_types = [c.type for c in node.children]

			extends_node = next((c for c in node.children if c.type == "superclass"), None)
			if extends_node:
				base_class_name = self._get_type_name(extends_node)
				if class_name and base_class_name and not self._skip_type(base_class_name, node):
					caller_id = self._get_component_id(class_name)
					callee_id = self._resolve_java_type(base_class_name, node, top_level_nodes)
					self.call_relationships.append(CallRelationship(
						caller=caller_id,
						callee=callee_id,  
						call_line=node.start_point[0]+1,
						is_resolved=False  
					))
			else:
				logger.debug(f"   No superclass found for {class_name}")

		# 2. Interface Implementation: Class/enum/record implements interface
		if node.type in ["class_declaration", "enum_declaration", "record_declaration"]:
			implementer_name = self._get_identifier_name(node)
			implements_node = next((c for c in node.children if c.type == "super_interfaces"), None)
			if implements_node and implementer_name:
				for child in implements_node.children:
					if child.type == "type_list":
						for type_child in child.children:
							if type_child.type in ["type_identifier", "generic_type"]:
								interface_name = self._get_type_name(type_child)
								if interface_name and not self._skip_type(interface_name, node):
									caller_id = self._get_component_id(implementer_name)
									callee_id = self._resolve_java_type(interface_name, node, top_level_nodes)
									self.call_relationships.append(CallRelationship(
										caller=caller_id,
										callee=callee_id,  
										call_line=node.start_point[0]+1,
										is_resolved=False
									))

		# 3. Field Type Use: Class has field of another class/interface type
		if node.type == "field_declaration":
			containing_class = self._find_containing_class(node, top_level_nodes)
			type_node = next((c for c in node.children if c.type in ["type_identifier", "generic_type"]), None)
			if containing_class and type_node:
				field_type_name = self._get_type_name(type_node)
				if field_type_name and not self._skip_type(field_type_name, node):
					self.call_relationships.append(CallRelationship(
						caller=containing_class,
						callee=self._resolve_java_type(field_type_name, node, top_level_nodes),
						call_line=node.start_point[0]+1,
						is_resolved=False
					))

		# 4. Method Calls: Method calls on objects
		if node.type == "method_invocation":
			containing_class = self._find_containing_class(node, top_level_nodes)
			containing_method = self._find_containing_method(node)
			if containing_class:
				object_name = None
				method_name = None

				identifiers = [child.text.decode() for child in node.children if child.type == "identifier"]
				if len(identifiers) >= 2:
					object_name = identifiers[0]
					method_name = identifiers[1]
				elif identifiers:
					method_name = identifiers[0]

				if method_name:
					target_type = None

					caller_id = containing_method or containing_class

					if object_name and object_name[:1].isupper() and object_name in top_level_nodes:
						target_type = object_name
					elif object_name:
						target_type = self._find_variable_type(node, object_name, top_level_nodes)
						if not target_type and object_name in top_level_nodes:
							target_type = object_name
						if not target_type and object_name[:1].isupper() and not object_name.isupper():
							# CamelCase receiver with no matching variable reads
							# as a static call on a type from another file or an
							# import; ALL_CAPS receivers are constants, not types.
							target_type = object_name

					if target_type and not self._skip_type(target_type, node):
						callee = self._resolve_java_member(method_name, node, top_level_nodes, target_type)
						if callee not in top_level_nodes and method_name in JAVA_OBJECT_METHODS:
							# Inherited java.lang.Object method that the project
							# type does not override locally — never a project edge.
							callee = None
						if callee:
							self.call_relationships.append(CallRelationship(
								caller=caller_id,
								callee=callee,
								call_line=node.start_point[0]+1,
								is_resolved=False
							))
					elif not object_name:
						callee = self._resolve_java_member(method_name, node, top_level_nodes)
						if callee in top_level_nodes or self.import_map.get(method_name) == callee:
							self.call_relationships.append(CallRelationship(
								caller=caller_id,
								callee=callee,
								call_line=node.start_point[0]+1,
								is_resolved=False
							))

		# 5. Object Creation
		if node.type == "object_creation_expression":
			containing_class = self._find_containing_class(node, top_level_nodes)
			type_node = next((c for c in node.children if c.type in ["type_identifier", "generic_type"]), None)
			if containing_class and type_node:
				created_type = self._get_type_name(type_node)
				if created_type and not self._skip_type(created_type, node):
						self.call_relationships.append(CallRelationship(
							caller=containing_class,
							callee=self._resolve_java_type(created_type, node, top_level_nodes),
							call_line=node.start_point[0]+1,
							is_resolved=False
						))

		# Recursively process children
		for child in node.children:
			self._extract_relationships(child, top_level_nodes)

	def _is_primitive_type(self, type_name: str) -> bool:
		"""Check if type is a Java primitive or a JDK/runtime type."""
		primitives = {
			"boolean", "byte", "char", "double", "float", "int", "long", "short",
			"void", "var",
		}
		simple = self._simple_type_name(type_name)
		if simple in primitives:
			return True
		# Resolve through the import map first so a runtime type written with its
		# simple name (imported from a `javax.*`/`java.*` package) is judged by its
		# fully-qualified origin. The prefix rules in is_external_symbol then
		# filter JDK/runtime packages, while project types — including sibling
		# packages like `com.other.Bar` — fall through and resolve cross-file. This
		# generalizes JDK filtering to any repository without enumerating types.
		# java.lang types (no import to consult) are covered by the curated set
		# inside is_external_symbol.
		qualified = self.import_map.get(simple)
		if qualified is None:
			# A wildcard import of a JDK package (`import java.util.*;`) is the
			# only way a JDK type outside java.lang appears with no explicit
			# import; project wildcard packages fall through to resolution.
			for wildcard in self.wildcard_imports:
				if is_external_symbol("java", f"{wildcard}.{simple}"):
					return True
			qualified = simple
		return is_external_symbol("java", qualified)

	def _resolve_java_type(self, type_name: str, context_node=None, top_level_nodes=None) -> str:
		if not type_name:
			return type_name
		type_name = self._simple_type_name(type_name)
		if "." in type_name:
			return type_name
		if type_name in self.import_map:
			return self.import_map[type_name]
		if context_node is not None and top_level_nodes is not None:
			containing_types = self._find_containing_type_names(context_node)
			for idx in range(len(containing_types), 0, -1):
				candidate = self._qualify_name(".".join([*containing_types[:idx], type_name]))
				if candidate in top_level_nodes:
					return candidate
		if self.package_name:
			return f"{self.package_name}.{type_name}"
		return type_name

	def _resolve_java_member(self, member_name: str, context_node, top_level_nodes, target_type: str = None) -> str:
		if target_type:
			qualified_type = self._resolve_java_type(target_type, context_node, top_level_nodes)
			candidate = f"{qualified_type}.{member_name}"
			if candidate in top_level_nodes:
				return candidate
			simple_type = qualified_type.split(".")[-1]
			simple_candidate = f"{simple_type}.{member_name}"
			if simple_candidate in top_level_nodes:
				return simple_candidate
			return candidate

		containing_types = self._find_containing_type_names(context_node)
		for idx in range(len(containing_types), 0, -1):
			candidate = self._qualified_member_name(containing_types[:idx], member_name)
			if candidate in top_level_nodes:
				return candidate
		# A static import maps the bare call to its declaring type, whether
		# project (`com.foo.Util.checkNotNull`) or JDK (`java.util.Objects.requireNonNull`).
		if member_name in self.import_map:
			return self.import_map[member_name]
		return self._qualify_name(member_name)

	def _skip_type(self, type_name: str, context_node) -> bool:
		"""Types that can never be project components: primitives, JDK/runtime
		types, and generic type parameters in scope (e.g. the `K`/`V` of an
		enclosing `class Cache<K, V>`)."""
		if self._is_primitive_type(type_name):
			return True
		return self._simple_type_name(type_name) in self._find_type_parameters(context_node)

	def _find_type_parameters(self, node) -> set:
		params = set()
		current = node
		while current:
			if current.type in [
				"class_declaration",
				"interface_declaration",
				"record_declaration",
				"method_declaration",
			]:
				type_parameters = next(
					(c for c in current.children if c.type == "type_parameters"), None
				)
				if type_parameters:
					for param in type_parameters.children:
						if param.type == "type_parameter":
							for child in param.children:
								if child.type in ["type_identifier", "identifier"]:
									params.add(child.text.decode())
									break
			current = current.parent
		return params

	def _simple_type_name(self, type_name: str) -> str:
		return type_name.strip().split("<", 1)[0].strip()

	def _qualify_name(self, name: str) -> str:
		return f"{self.package_name}.{name}" if self.package_name else name

	def _qualified_type_name(self, name: str, containing_types: list[str]) -> str:
		parts = [*containing_types, name] if name else containing_types
		return self._qualify_name(".".join(parts)) if parts else ""

	def _qualified_member_name(self, containing_types: list[str], member_name: str) -> str:
		return self._qualify_name(".".join([*containing_types, member_name]))

	def _get_identifier_name(self, node):
		"""Get identifier name from a node."""
		name_node = next((c for c in node.children if c.type == "identifier"), None)
		return name_node.text.decode() if name_node else None

	def _get_type_name(self, node):
		"""Get type name from a type node."""
		if node.type == "type_identifier":
			return node.text.decode()
		elif node.type == "generic_type":
			type_node = next((c for c in node.children if c.type == "type_identifier"), None)
			return type_node.text.decode() if type_node else None
		elif node.type == "superclass":
			type_node = next((c for c in node.children if c.type == "type_identifier"), None)
			return type_node.text.decode() if type_node else None
		return None

	def _find_containing_class(self, node, top_level_nodes):
		current = node.parent
		while current:
			if current.type in ["class_declaration", "interface_declaration", "enum_declaration", "record_declaration", "annotation_type_declaration"]:
				class_name = self._get_identifier_name(current)
				if class_name and class_name in top_level_nodes:
					return self._get_component_id(class_name)  
			current = current.parent
		return None

	def _find_variable_type(self, node, variable_name, top_level_nodes):
		method_node = node.parent
		while method_node and method_node.type not in ["method_declaration", "constructor_declaration"]:
			method_node = method_node.parent

		if method_node:
			for child in method_node.children:
				if child.type == "block" or child.type == "constructor_body":
					variable_type = self._search_variable_declaration(child, variable_name)
					if variable_type:
						return variable_type
				elif child.type == "formal_parameters":
					for param in child.children:
						if param.type in ["formal_parameter", "spread_parameter"]:
							type_node = next(
								(c for c in param.children if c.type in ["type_identifier", "generic_type"]),
								None,
							)
							identifier_node = next(
								(c for c in param.children if c.type == "identifier"), None
							)
							if (
								type_node
								and identifier_node
								and identifier_node.text.decode() == variable_name
							):
								return self._get_type_name(type_node)

		class_node = node.parent
		while class_node and class_node.type != "class_declaration":
			class_node = class_node.parent

		if class_node:
			for child in class_node.children:
				if child.type == "class_body":
					for body_child in child.children:
						if body_child.type == "field_declaration":
							identifier_node = None
							type_node = None
							for field_child in body_child.children:
								if field_child.type in ["type_identifier", "generic_type"]:
									type_node = field_child
								elif field_child.type == "variable_declarator":
									identifier_node = next((c for c in field_child.children if c.type == "identifier"), None)

							if identifier_node and type_node and identifier_node.text.decode() == variable_name:
								field_type = self._get_type_name(type_node)
								return field_type

		return None

	def _search_variable_declaration(self, block_node, variable_name):
		for child in block_node.children:
			if child.type == "local_variable_declaration":
				type_node = None
				identifier_node = None
				for decl_child in child.children:
					if decl_child.type in ["type_identifier", "generic_type"]:
						type_node = decl_child
					elif decl_child.type == "variable_declarator":
						identifier_node = next((c for c in decl_child.children if c.type == "identifier"), None)

				if identifier_node and type_node and identifier_node.text.decode() == variable_name:
					return self._get_type_name(type_node)

			elif child.type == "block":
				result = self._search_variable_declaration(child, variable_name)
				if result:
					return result

		return None

	def _find_containing_class_name(self, node):
		names = self._find_containing_type_names(node)
		return names[-1] if names else None

	def _find_containing_type_names(self, node) -> list[str]:
		names = []
		current = node.parent
		while current:
			if current.type in ["class_declaration", "interface_declaration", "enum_declaration", "record_declaration", "annotation_type_declaration"]:
				name_node = next((c for c in current.children if c.type == "identifier"), None)
				if name_node:
					names.append(name_node.text.decode())
			current = current.parent
		return list(reversed(names))

	def _find_containing_method(self, node):
		current = node.parent
		while current:
			if current.type == "method_declaration":
				method_name = self._get_identifier_name(current)
				class_name = self._find_containing_class_name(current)
				if method_name and class_name:
					return self._get_component_id(f"{class_name}.{method_name}")
			current = current.parent
		return None

def _get_module_path(self) -> str:
	if self.repo_path:
		try:
			rel_path = os.path.relpath(str(self.file_path), self.repo_path)
		except ValueError:
			rel_path = str(self.file_path)
	else:
		rel_path = str(self.file_path)

	for ext in ['.java']:
		if rel_path.endswith(ext):
			rel_path = rel_path[:-len(ext)]
			break
	return rel_path.replace('/', '.').replace('\\', '.')

def _get_relative_path(self) -> str:
	"""Get relative path from repo root."""
	if self.repo_path:
		try:
			return os.path.relpath(str(self.file_path), self.repo_path)
		except ValueError:
			return str(self.file_path)
	else:
		return str(self.file_path)

def _get_component_id(self, name: str, parent_class: str = None) -> str:
	rel_path = self._get_relative_path()
	if parent_class:
		return f"{rel_path}::{parent_class}.{name}"
	else:
		return f"{rel_path}::{name}"

def _extract_package_name(self) -> str:
	match = re.search(r"^\s*package\s+([\w.]+)\s*;", self.content, re.MULTILINE)
	return match.group(1) if match else ""

def _extract_imports(self) -> tuple[dict[str, str], list[str]]:
	import_map: dict[str, str] = {}
	wildcards: list[str] = []
	for match in re.finditer(r"^\s*import\s+(?:static\s+)?([\w.]+)(\.\*)?\s*;", self.content, re.MULTILINE):
		import_name = match.group(1)
		if match.group(2):
			wildcards.append(import_name)
		else:
			import_map[import_name.rsplit(".", 1)[-1]] = import_name
	return import_map, wildcards

def _extract_relationships(self, node, top_level_nodes):
	# 1. Inheritance: Class extends another class
	if node.type == "class_declaration":
		class_name = self._get_identifier_name(node)
		children_types = [c.type for c in node.children]

		extends_node = next((c for c in node.children if c.type == "superclass"), None)
		if extends_node:
			base_class_name = self._get_type_name(extends_node)
			if class_name and base_class_name and not self._skip_type(base_class_name, node):
				caller_id = self._get_component_id(class_name)
				callee_id = self._resolve_java_type(base_class_name, node, top_level_nodes)
				self.call_relationships.append(CallRelationship(
					caller=caller_id,
					callee=callee_id,  
					call_line=node.start_point[0]+1,
					is_resolved=False  
				))
		else:
			logger.debug(f"   No superclass found for {class_name}")

	# 2. Interface Implementation: Class/enum/record implements interface
	if node.type in ["class_declaration", "enum_declaration", "record_declaration"]:
		implementer_name = self._get_identifier_name(node)
		implements_node = next((c for c in node.children if c.type == "super_interfaces"), None)
		if implements_node and implementer_name:
			for child in implements_node.children:
				if child.type == "type_list":
					for type_child in child.children:
						if type_child.type in ["type_identifier", "generic_type"]:
							interface_name = self._get_type_name(type_child)
							if interface_name and not self._skip_type(interface_name, node):
								caller_id = self._get_component_id(implementer_name)
								callee_id = self._resolve_java_type(interface_name, node, top_level_nodes)
								self.call_relationships.append(CallRelationship(
									caller=caller_id,
									callee=callee_id,  
									call_line=node.start_point[0]+1,
									is_resolved=False
								))

	# 3. Field Type Use: Class has field of another class/interface type
	if node.type == "field_declaration":
		containing_class = self._find_containing_class(node, top_level_nodes)
		type_node = next((c for c in node.children if c.type in ["type_identifier", "generic_type"]), None)
		if containing_class and type_node:
			field_type_name = self._get_type_name(type_node)
			if field_type_name and not self._skip_type(field_type_name, node):
				self.call_relationships.append(CallRelationship(
					caller=containing_class,
					callee=self._resolve_java_type(field_type_name, node, top_level_nodes),
					call_line=node.start_point[0]+1,
					is_resolved=False
				))

	# 4. Method Calls: Method calls on objects
	if node.type == "method_invocation":
		containing_class = self._find_containing_class(node, top_level_nodes)
		containing_method = self._find_containing_method(node)
		if containing_class:
			object_name = None
			method_name = None

			identifiers = [child.text.decode() for child in node.children if child.type == "identifier"]
			if len(identifiers) >= 2:
				object_name = identifiers[0]
				method_name = identifiers[1]
			elif identifiers:
				method_name = identifiers[0]

			if method_name:
				target_type = None

				caller_id = containing_method or containing_class

				if object_name and object_name[:1].isupper() and object_name in top_level_nodes:
					target_type = object_name
				elif object_name:
					target_type = self._find_variable_type(node, object_name, top_level_nodes)
					if not target_type and object_name in top_level_nodes:
						target_type = object_name
					if not target_type and object_name[:1].isupper() and not object_name.isupper():
						# CamelCase receiver with no matching variable reads
						# as a static call on a type from another file or an
						# import; ALL_CAPS receivers are constants, not types.
						target_type = object_name

				if target_type and not self._skip_type(target_type, node):
					callee = self._resolve_java_member(method_name, node, top_level_nodes, target_type)
					if callee not in top_level_nodes and method_name in JAVA_OBJECT_METHODS:
						# Inherited java.lang.Object method that the project
						# type does not override locally — never a project edge.
						callee = None
					if callee:
						self.call_relationships.append(CallRelationship(
							caller=caller_id,
							callee=callee,
							call_line=node.start_point[0]+1,
							is_resolved=False
						))
				elif not object_name:
					callee = self._resolve_java_member(method_name, node, top_level_nodes)
					if callee in top_level_nodes or self.import_map.get(method_name) == callee:
						self.call_relationships.append(CallRelationship(
							caller=caller_id,
							callee=callee,
							call_line=node.start_point[0]+1,
							is_resolved=False
						))

	# 5. Object Creation
	if node.type == "object_creation_expression":
		containing_class = self._find_containing_class(node, top_level_nodes)
		type_node = next((c for c in node.children if c.type in ["type_identifier", "generic_type"]), None)
		if containing_class and type_node:
			created_type = self._get_type_name(type_node)
			if created_type and not self._skip_type(created_type, node):
					self.call_relationships.append(CallRelationship(
						caller=containing_class,
						callee=self._resolve_java_type(created_type, node, top_level_nodes),
						call_line=node.start_point[0]+1,
						is_resolved=False
					))

	# Recursively process children
	for child in node.children:
		self._extract_relationships(child, top_level_nodes)

def _resolve_java_type(self, type_name: str, context_node=None, top_level_nodes=None) -> str:
	if not type_name:
		return type_name
	type_name = self._simple_type_name(type_name)
	if "." in type_name:
		return type_name
	if type_name in self.import_map:
		return self.import_map[type_name]
	if context_node is not None and top_level_nodes is not None:
		containing_types = self._find_containing_type_names(context_node)
		for idx in range(len(containing_types), 0, -1):
			candidate = self._qualify_name(".".join([*containing_types[:idx], type_name]))
			if candidate in top_level_nodes:
				return candidate
	if self.package_name:
		return f"{self.package_name}.{type_name}"
	return type_name

def _resolve_java_member(self, member_name: str, context_node, top_level_nodes, target_type: str = None) -> str:
	if target_type:
		qualified_type = self._resolve_java_type(target_type, context_node, top_level_nodes)
		candidate = f"{qualified_type}.{member_name}"
		if candidate in top_level_nodes:
			return candidate
		simple_type = qualified_type.split(".")[-1]
		simple_candidate = f"{simple_type}.{member_name}"
		if simple_candidate in top_level_nodes:
			return simple_candidate
		return candidate

	containing_types = self._find_containing_type_names(context_node)
	for idx in range(len(containing_types), 0, -1):
		candidate = self._qualified_member_name(containing_types[:idx], member_name)
		if candidate in top_level_nodes:
			return candidate
	# A static import maps the bare call to its declaring type, whether
	# project (`com.foo.Util.checkNotNull`) or JDK (`java.util.Objects.requireNonNull`).
	if member_name in self.import_map:
		return self.import_map[member_name]
	return self._qualify_name(member_name)

def _skip_type(self, type_name: str, context_node) -> bool:
	"""Types that can never be project components: primitives, JDK/runtime
	types, and generic type parameters in scope (e.g. the `K`/`V` of an
	enclosing `class Cache<K, V>`)."""
	if self._is_primitive_type(type_name):
		return True
	return self._simple_type_name(type_name) in self._find_type_parameters(context_node)

def _find_type_parameters(self, node) -> set:
	params = set()
	current = node
	while current:
		if current.type in [
			"class_declaration",
			"interface_declaration",
			"record_declaration",
			"method_declaration",
		]:
			type_parameters = next(
				(c for c in current.children if c.type == "type_parameters"), None
			)
			if type_parameters:
				for param in type_parameters.children:
					if param.type == "type_parameter":
						for child in param.children:
							if child.type in ["type_identifier", "identifier"]:
								params.add(child.text.decode())
								break
		current = current.parent
	return params

def _qualified_type_name(self, name: str, containing_types: list[str]) -> str:
	parts = [*containing_types, name] if name else containing_types
	return self._qualify_name(".".join(parts)) if parts else ""

def _get_type_name(self, node):
	"""Get type name from a type node."""
	if node.type == "type_identifier":
		return node.text.decode()
	elif node.type == "generic_type":
		type_node = next((c for c in node.children if c.type == "type_identifier"), None)
		return type_node.text.decode() if type_node else None
	elif node.type == "superclass":
		type_node = next((c for c in node.children if c.type == "type_identifier"), None)
		return type_node.text.decode() if type_node else None
	return None

def _find_containing_class(self, node, top_level_nodes):
	current = node.parent
	while current:
		if current.type in ["class_declaration", "interface_declaration", "enum_declaration", "record_declaration", "annotation_type_declaration"]:
			class_name = self._get_identifier_name(current)
			if class_name and class_name in top_level_nodes:
				return self._get_component_id(class_name)  
		current = current.parent
	return None

def _find_variable_type(self, node, variable_name, top_level_nodes):
	method_node = node.parent
	while method_node and method_node.type not in ["method_declaration", "constructor_declaration"]:
		method_node = method_node.parent

	if method_node:
		for child in method_node.children:
			if child.type == "block" or child.type == "constructor_body":
				variable_type = self._search_variable_declaration(child, variable_name)
				if variable_type:
					return variable_type
			elif child.type == "formal_parameters":
				for param in child.children:
					if param.type in ["formal_parameter", "spread_parameter"]:
						type_node = next(
							(c for c in param.children if c.type in ["type_identifier", "generic_type"]),
							None,
						)
						identifier_node = next(
							(c for c in param.children if c.type == "identifier"), None
						)
						if (
							type_node
							and identifier_node
							and identifier_node.text.decode() == variable_name
						):
							return self._get_type_name(type_node)

	class_node = node.parent
	while class_node and class_node.type != "class_declaration":
		class_node = class_node.parent

	if class_node:
		for child in class_node.children:
			if child.type == "class_body":
				for body_child in child.children:
					if body_child.type == "field_declaration":
						identifier_node = None
						type_node = None
						for field_child in body_child.children:
							if field_child.type in ["type_identifier", "generic_type"]:
								type_node = field_child
							elif field_child.type == "variable_declarator":
								identifier_node = next((c for c in field_child.children if c.type == "identifier"), None)

						if identifier_node and type_node and identifier_node.text.decode() == variable_name:
							field_type = self._get_type_name(type_node)
							return field_type

	return None

def _search_variable_declaration(self, block_node, variable_name):
	for child in block_node.children:
		if child.type == "local_variable_declaration":
			type_node = None
			identifier_node = None
			for decl_child in child.children:
				if decl_child.type in ["type_identifier", "generic_type"]:
					type_node = decl_child
				elif decl_child.type == "variable_declarator":
					identifier_node = next((c for c in decl_child.children if c.type == "identifier"), None)

			if identifier_node and type_node and identifier_node.text.decode() == variable_name:
				return self._get_type_name(type_node)

		elif child.type == "block":
			result = self._search_variable_declaration(child, variable_name)
			if result:
				return result

	return None

def _find_containing_class_name(self, node):
	names = self._find_containing_type_names(node)
	return names[-1] if names else None

def _find_containing_type_names(self, node) -> list[str]:
	names = []
	current = node.parent
	while current:
		if current.type in ["class_declaration", "interface_declaration", "enum_declaration", "record_declaration", "annotation_type_declaration"]:
			name_node = next((c for c in current.children if c.type == "identifier"), None)
			if name_node:
				names.append(name_node.text.decode())
		current = current.parent
	return list(reversed(names))

def _find_containing_method(self, node):
	current = node.parent
	while current:
		if current.type == "method_declaration":
			method_name = self._get_identifier_name(current)
			class_name = self._find_containing_class_name(current)
			if method_name and class_name:
				return self._get_component_id(f"{class_name}.{method_name}")
		current = current.parent
	return None

def analyze_java_file(file_path: str, content: str, repo_path: str = None) -> Tuple[List[Node], List[CallRelationship]]:
	analyzer = TreeSitterJavaAnalyzer(file_path, content, repo_path)
	return analyzer.nodes, analyzer.call_relationships

class TreeSitterJSAnalyzer:
    def __init__(self, file_path: str, content: str, repo_path: str = None):
        self.file_path = Path(file_path)
        self.content = content
        self.repo_path = repo_path or ""
        self.nodes: List[Node] = []
        self.call_relationships: List[CallRelationship] = []

        self.top_level_nodes = {}

        self.seen_relationships = set()

        try:
            language_capsule = tree_sitter_javascript.language()
            self.js_language = Language(language_capsule)
            self.parser = Parser(self.js_language)

        except Exception as e:
            logger.error(f"Failed to initialize JavaScript parser: {e}")
            logger.error(f"Traceback: {traceback.format_exc()}")
            self.parser = None
            self.js_language = None


    def _add_relationship(self, relationship: CallRelationship) -> bool:
        rel_key = (relationship.caller, relationship.callee, relationship.call_line)

        if rel_key not in self.seen_relationships:
            self.seen_relationships.add(rel_key)
            self.call_relationships.append(relationship)
            return True
        return False

    def analyze(self) -> None:
        if self.parser is None:
            logger.warning(f"Skipping {self.file_path} - parser initialization failed")
            return

        try:
            tree = self.parser.parse(bytes(self.content, "utf8"))
            root_node = tree.root_node

            logger.debug(f"Parsed AST with root node type: {root_node.type}")

            self._extract_functions(root_node)
            self._extract_call_relationships(root_node)

            logger.debug(
                f"Analysis complete: {len(self.nodes)} nodes, {len(self.call_relationships)} relationships"
            )

        except Exception as e:
            logger.error(f"Error analyzing JavaScript file {self.file_path}: {e}", exc_info=True)

    def _get_module_path(self) -> str:
        if self.repo_path:
            try:
                rel_path = os.path.relpath(str(self.file_path), self.repo_path)
            except ValueError:
                rel_path = str(self.file_path)
        else:
            rel_path = str(self.file_path)

        for ext in ['.js', '.ts', '.jsx', '.tsx', '.mjs', '.cjs']:
            if rel_path.endswith(ext):
                rel_path = rel_path[:-len(ext)]
                break
        return rel_path.replace('/', '.').replace('\\', '.')

    def _get_relative_path(self) -> str:
        if self.repo_path:
            try:
                return os.path.relpath(str(self.file_path), self.repo_path)
            except ValueError:
                return str(self.file_path)
        else:
            return str(self.file_path)

    def _get_component_id(self, name: str, class_name: str = None, is_method: bool = False) -> str:
        relative_path = self._get_relative_path()

        if is_method and class_name:
            return f"{relative_path}::{class_name}.{name}"
        elif class_name and not is_method:
            return f"{relative_path}::{name}"
        else:
            return f"{relative_path}::{name}"

    def _find_containing_class(self, node) -> Optional[str]:
        parent = node.parent
        while parent:
            if parent.type in ["class_declaration", "abstract_class_declaration", "interface_declaration"]:
                name_node = self._find_child_by_type(parent, "type_identifier")
                if not name_node:
                    name_node = self._find_child_by_type(parent, "identifier")
                if name_node:
                    return self._get_node_text(name_node)
            parent = parent.parent
        return None

    def _extract_functions(self, node) -> None:
        self._traverse_for_functions(node)
        self.nodes.sort(key=lambda n: n.start_line)

    def _traverse_for_functions(self, node) -> None:
        if node.type in ["class_declaration", "abstract_class_declaration", "interface_declaration"]:
            cls = self._extract_class_declaration(node)
            if cls:
                self.nodes.append(cls)
                self.top_level_nodes[cls.name] = cls

                self._extract_methods_from_class(node, cls.name)

        elif node.type == "function_declaration":
            containing_class = self._find_containing_class(node)
            if containing_class is None:
                func = self._extract_function_declaration(node)
                if func and self._should_include_function(func):
                    self.nodes.append(func)
                    self.top_level_nodes[func.name] = func
        elif node.type == "generator_function_declaration":
            containing_class = self._find_containing_class(node)
            if containing_class is None:
                func = self._extract_function_declaration(node)
                if func and self._should_include_function(func):
                    self.nodes.append(func)
                    self.top_level_nodes[func.name] = func
        elif node.type == "export_statement":
            func = self._extract_exported_function(node)
            if func and self._should_include_function(func):
                self.nodes.append(func)
                self.top_level_nodes[func.name] = func
        elif node.type == "lexical_declaration":
            containing_class = self._find_containing_class(node)
            if containing_class is None:
                func = self._extract_arrow_function_from_declaration(node)
                if func and self._should_include_function(func):
                    self.nodes.append(func)
                    self.top_level_nodes[func.name] = func

        for child in node.children:
            self._traverse_for_functions(child)

    def _extract_methods_from_class(self, class_node, class_name: str) -> None:
        class_body = self._find_child_by_type(class_node, "class_body")
        if not class_body:
            return

        for child in class_body.children:
            if child.type == "method_definition":
                method_name = self._get_method_name(child)
                if method_name:
                    method_node = self._create_method_node(child, method_name, class_name)
                    if method_node:
                        if method_name != "constructor":
                            self.nodes.append(method_node)
                        self.top_level_nodes[method_node.name] = method_node
            elif child.type == "field_definition":
                # Handle arrow function properties
                field_name = self._get_field_name(child)
                if field_name and self._is_arrow_function_field(child):
                    method_node = self._create_method_node(child, field_name, class_name)
                    if method_node:
                        self.nodes.append(method_node)
                        self.top_level_nodes[method_node.name] = method_node

    def _get_method_name(self, method_node) -> Optional[str]:
        """Get method name from method_definition node."""
        if method_node.type != "method_definition":
            return None

        for child in method_node.children:
            if child.type == "property_identifier":
                return self._get_node_text(child)
        return None

    def _get_field_name(self, field_node) -> Optional[str]:
        """Get field name from field_definition node."""
        if field_node.type != "field_definition":
            return None

        for child in field_node.children:
            if child.type == "property_identifier":
                return self._get_node_text(child)
        return None

    def _is_arrow_function_field(self, field_node) -> bool:
        """Check if field_definition contains an arrow function."""
        for child in field_node.children:
            if child.type == "arrow_function":
                return True
        return False

    def _create_method_node(self, node, method_name: str, class_name: str) -> Optional[Node]:
        """Create a method node for relationship mapping."""
        try:
            line_start = node.start_point[0] + 1
            line_end = node.end_point[0] + 1
            component_id = self._get_component_id(method_name, class_name, is_method=True)
            relative_path = self._get_relative_path()
            qualified = f"{class_name}.{method_name}"

            return Node(
                id=component_id,
                name=qualified,
                component_type="method",
                file_path=str(self.file_path),
                relative_path=relative_path,
                source_code="\n".join(self.content.splitlines()[line_start - 1 : line_end]),
                start_line=line_start,
                end_line=line_end,
                has_docstring=False,
                docstring="",
                parameters=None,
                node_type="method",
                base_classes=None,
                class_name=class_name,
                display_name=f"method {qualified}",
                component_id=component_id,
                language="javascript",
                qualified_name=qualified,
            )
        except Exception as e:
            logger.debug(f"Error creating method node for {method_name}: {e}")
            return None

    def _extract_class_declaration(self, node) -> Optional[Node]:
        """Extract class/abstract class/interface declaration."""
        try:
            name_node = self._find_child_by_type(node, "type_identifier")
            if not name_node:
                name_node = self._find_child_by_type(node, "identifier")
            if not name_node:
                return None
            name = self._get_node_text(name_node)
            line_start = node.start_point[0] + 1
            line_end = node.end_point[0] + 1
            docstring = None
            base_classes = []
            heritage_node = self._find_child_by_type(node, "class_heritage")
            if heritage_node:
                for child in heritage_node.children:
                    if child.type in ["identifier", "type_identifier"]:
                        base_classes.append(self._get_node_text(child))
            code_snippet = "\n".join(self.content.splitlines()[line_start - 1 : line_end])

            if node.type == "abstract_class_declaration":
                node_type = "abstract class"
                display_name = f"abstract class {name}"
            elif node.type == "interface_declaration":
                node_type = "interface"
                display_name = f"interface {name}"
            else:
                node_type = "class"
                display_name = f"class {name}"

            component_id = self._get_component_id(name, is_method=False)
            relative_path = self._get_relative_path()

            return Node(
                id=component_id,
                name=name,
                component_type=node_type,
                file_path=str(self.file_path),
                relative_path=relative_path,
                source_code=code_snippet,
                start_line=line_start,
                end_line=line_end,
                has_docstring=bool(docstring),
                docstring=docstring or "",
                parameters=None,
                node_type=node_type,
                base_classes=base_classes if base_classes else None,
                class_name=None,
                display_name=display_name,
                component_id=component_id,
            )
        except Exception:
            return None

    def _extract_function_declaration(self, node) -> Optional[Node]:
        try:
            name_node = self._find_child_by_type(node, "identifier")
            if not name_node:
                return None

            func_name = self._get_node_text(name_node)
            line_start = node.start_point[0] + 1
            line_end = node.end_point[0] + 1
            parameters = self._extract_parameters(node)
            code_snippet = self._get_node_text(node)

            # Check for async and generator from code snippet
            is_async = "async function" in code_snippet
            is_generator = "function*" in code_snippet or "*" in func_name

            if is_async and is_generator:
                display_name = f"async generator {func_name}"
            elif is_async:
                display_name = f"async function {func_name}"
            elif is_generator:
                display_name = f"generator function {func_name}"
            else:
                display_name = f"function {func_name}"

            component_id = self._get_component_id(func_name, is_method=False)
            relative_path = self._get_relative_path()

            return Node(
                id=component_id,
                name=func_name,
                component_type="function",
                file_path=str(self.file_path),
                relative_path=relative_path,
                source_code=code_snippet,
                start_line=line_start,
                end_line=line_end,
                has_docstring=False,
                docstring="",
                parameters=parameters,
                node_type="function",
                base_classes=None,
                class_name=None,
                display_name=display_name,
                component_id=component_id,
            )
        except Exception as e:
            logger.debug(f"Error extracting function declaration: {e}")
            return None
    def _extract_exported_function(self, node) -> Optional[Node]:
        """Extract export function or export default function"""
        try:
            func_decl = self._find_child_by_type(node, "function_declaration")
            if func_decl:
                func = self._extract_function_declaration(func_decl)
                if func:
                    export_text = self._get_node_text(node)
                    if "export default" in export_text and "function (" in export_text:
                        func.name = "default"
                return func
        except Exception as e:
            logger.debug(f"Error extracting exported function: {e}")
        return None

    def _extract_arrow_function_from_declaration(self, node) -> Optional[Node]:
        """Extract arrow function or function expression from const/let/var declarations."""
        try:
            for child in node.children:
                if child.type == "variable_declarator":
                    name_node = self._find_child_by_type(child, "identifier")
                    func_node = self._find_child_by_type(
                        child, "arrow_function"
                    ) or self._find_child_by_type(child, "function_expression")

                    if name_node and func_node:
                        func_name = self._get_node_text(name_node)
                        line_start = func_node.start_point[0] + 1
                        line_end = func_node.end_point[0] + 1
                        parameters = self._extract_parameters(func_node)
                        code_snippet = self._get_node_text(child)

                        component_id = self._get_component_id(func_name, is_method=False)
                        relative_path = self._get_relative_path()

                        return Node(
                            id=component_id,
                            name=func_name,
                            component_type="function",
                            file_path=str(self.file_path),
                            relative_path=relative_path,
                            source_code=code_snippet,
                            start_line=line_start,
                            end_line=line_end,
                            has_docstring=False,
                            docstring="",
                            parameters=parameters,
                            node_type="function",
                            base_classes=None,
                            class_name=None,
                            display_name=f"function {func_name}",
                            component_id=component_id,
                        )
            return None
        except Exception as e:
            logger.debug(f"Error extracting function from declaration: {e}")
        return None

    def _should_include_function(self, func: Node) -> bool:
        excluded_names = {}

        if func.name.lower() in excluded_names:
            logger.debug(f"Skipping excluded function: {func.name}")
            return False

        return True

    def _extract_parameters(self, node) -> List[str]:
        parameters = []
        params_node = self._find_child_by_type(node, "formal_parameters")
        if params_node:
            for child in params_node.children:
                if child.type == "identifier":
                    parameters.append(self._get_node_text(child))
        return parameters

    def _extract_call_relationships(self, node) -> None:
        current_top_level = None
        self._traverse_for_calls(node, current_top_level)

    def _traverse_for_calls(self, node, current_top_level) -> None:
        if current_top_level:
            self._extract_jsdoc_type_dependencies(node, current_top_level)

        if node.type in ["class_declaration", "abstract_class_declaration", "interface_declaration"]:
            name_node = self._find_child_by_type(node, "type_identifier") or self._find_child_by_type(node, "identifier")
            if name_node:
                current_top_level = self._get_node_text(name_node)

                heritage_node = self._find_child_by_type(node, "class_heritage")
                if heritage_node:
                    for child in heritage_node.children:
                        if child.type in ["identifier", "type_identifier"]:
                            base_class = self._get_node_text(child)
                            caller_id = self._get_component_id(current_top_level)
                            resolved = base_class in self.top_level_nodes
                            callee_id = self._get_component_id(base_class) if resolved else base_class
                            inheritance_rel = CallRelationship(
                                caller=caller_id,
                                callee=callee_id,
                                call_line=node.start_point[0] + 1,
                                is_resolved=resolved
                            )
                            self._add_relationship(inheritance_rel)

        elif node.type in ("method_definition", "field_definition"):
            name = self._get_method_name(node) if node.type == "method_definition" else self._get_field_name(node)
            containing_class = self._find_containing_class(node)
            if name and containing_class and f"{containing_class}.{name}" in self.top_level_nodes:
                current_top_level = f"{containing_class}.{name}"

        elif node.type == "function_declaration":
            name_node = self._find_child_by_type(node, "identifier")
            if name_node:
                current_top_level = self._get_node_text(name_node)
        elif node.type == "generator_function_declaration":
            name_node = self._find_child_by_type(node, "identifier")
            if name_node:
                current_top_level = self._get_node_text(name_node)
        elif node.type == "lexical_declaration":
            for child in node.children:
                if child.type == "variable_declarator":
                    name_node = self._find_child_by_type(child, "identifier")
                    func_node = self._find_child_by_type(child, "arrow_function") or self._find_child_by_type(child, "function_expression")
                    if name_node and func_node:
                        current_top_level = self._get_node_text(name_node)

        if node.type == "call_expression" and current_top_level:
            call_info = self._extract_call_from_node(node, current_top_level)
            if call_info:
                self._add_relationship(call_info)

        elif node.type == "await_expression" and current_top_level:
            call_expr = self._find_child_by_type(node, "call_expression")
            if call_expr:
                call_info = self._extract_call_from_node(call_expr, current_top_level)
                if call_info:
                    self._add_relationship(call_info)

        elif node.type == "new_expression" and current_top_level:
            constructor_node = self._find_child_by_type(node, "identifier")
            if constructor_node is not None:
                callee_name = self._get_node_text(constructor_node)
                resolved = callee_name in self.top_level_nodes
                call_info = CallRelationship(
                    caller=f"{self._get_relative_path()}::{current_top_level}",
                    callee=self._get_component_id(callee_name) if resolved else callee_name,
                    call_line=node.start_point[0] + 1,
                    is_resolved=resolved
                )
                self._add_relationship(call_info)

        for child in node.children:
            self._traverse_for_calls(child, current_top_level)

    def _extract_call_from_node(self, node, caller_name: str) -> Optional[CallRelationship]:
        """Extract one relationship from a call_expression node.

        Plain identifier calls resolve against same-file components; member
        calls resolve receiver-first (this/super against the enclosing class,
        new-ed variables against their class). Unresolved callees stay bare
        logical names, never file-prefixed.
        """
        try:
            call_line = node.start_point[0] + 1
            caller_id = f"{self._get_relative_path()}::{caller_name}"
            func_node = node.children[0] if node.children else None
            if func_node is None:
                return None

            def make(callee_name: str, resolved: bool) -> CallRelationship:
                return CallRelationship(
                    caller=caller_id,
                    callee=self._get_component_id(callee_name) if resolved else callee_name,
                    call_line=call_line,
                    is_resolved=resolved,
                )

            if func_node.type == "identifier":
                name = self._get_node_text(func_node)
                if not name:
                    return None
                return make(name, name in self.top_level_nodes)

            if func_node.type != "member_expression":
                return None

            property_node = func_node.child_by_field_name("property")
            obj = func_node.child_by_field_name("object")
            if property_node is None or property_node.type != "property_identifier" or obj is None:
                return None
            tail = self._get_node_text(property_node)

            if obj.type in ("this", "super"):
                class_name = caller_name.split(".")[0]
                candidates = [] if obj.type == "super" else [class_name]
                class_node = self.top_level_nodes.get(class_name)
                if class_node is not None and class_node.base_classes:
                    candidates.extend(class_node.base_classes)
                for candidate in candidates:
                    if f"{candidate}.{tail}" in self.top_level_nodes:
                        return make(f"{candidate}.{tail}", True)
                target = candidates[0] if candidates else class_name
                return make(f"{target}.{tail}", False)

            if obj.type == "identifier":
                receiver = self._get_node_text(obj)
                if receiver in self.top_level_nodes or self._receiver_class(node, receiver):
                    cls = receiver if receiver in self.top_level_nodes else self._receiver_class(node, receiver)
                    return make(f"{cls}.{tail}", f"{cls}.{tail}" in self.top_level_nodes)
                return make(f"{receiver}.{tail}", False)

            if obj.type == "member_expression":
                chain = self._identifier_chain(obj)
                if chain:
                    return make(f"{chain}.{tail}", False)

            # Composite or literal receiver: a builtin-prototype method on an
            # unknowable receiver can never resolve to a project component.
            if tail not in JS_TS_PROTOTYPE_METHODS:
                return make(tail, False)
            return None

        except Exception as e:
            logger.debug(f"Error extracting call relationship: {e}")
            return None

    def _identifier_chain(self, node) -> Optional[str]:
        """Flatten a member expression into dotted text when it is a pure
        identifier chain; None when any link is computed."""
        parts = []
        current = node
        while current.type == "member_expression":
            property_node = current.child_by_field_name("property")
            if property_node is None or property_node.type != "property_identifier":
                return None
            parts.append(self._get_node_text(property_node))
            current = current.child_by_field_name("object")
            if current is None:
                return None
        if current.type != "identifier":
            return None
        parts.append(self._get_node_text(current))
        return ".".join(reversed(parts))

    def _receiver_class(self, call_node, identifier: str) -> Optional[str]:
        """Find the class of a local identifier from a `new X()` initializer
        in an enclosing scope."""
        scope = call_node.parent
        while scope:
            if scope.type in (
                "method_definition", "function_declaration",
                "generator_function_declaration", "arrow_function",
                "function_expression", "program",
            ):
                found = self._find_new_initializer(scope, identifier)
                if found:
                    return found
            scope = scope.parent
        return None

    def _find_new_initializer(self, scope_node, identifier: str) -> Optional[str]:
        stack = [scope_node]
        while stack:
            current = stack.pop()
            if current.type == "variable_declarator":
                name_node = self._find_child_by_type(current, "identifier")
                if name_node is not None and self._get_node_text(name_node) == identifier:
                    new_expr = self._find_child_by_type(current, "new_expression")
                    if new_expr is not None:
                        ctor = self._find_child_by_type(new_expr, "identifier")
                        if ctor is not None:
                            return self._get_node_text(ctor)
            stack.extend(current.children)
        return None

    def _extract_jsdoc_type_dependencies(self, node, caller_name: str) -> None:
        """Extract type dependencies from JSDoc comments."""
        try:
            if hasattr(node, 'prev_sibling') and node.prev_sibling:
                prev = node.prev_sibling
                if prev.type == "comment":
                    comment_text = self._get_node_text(prev)
                    self._parse_jsdoc_types(comment_text, caller_name, node.start_point[0] + 1)

            for child in node.children:
                if child.type == "comment":
                    comment_text = self._get_node_text(child)
                    self._parse_jsdoc_types(comment_text, caller_name, node.start_point[0] + 1)

        except Exception as e:
            logger.debug(f"Error extracting JSDoc dependencies: {e}")

    def _parse_jsdoc_types(self, comment_text: str, caller_name: str, line_number: int) -> None:
        """Parse JSDoc comment text and extract type references."""
        import re
        try:
            type_patterns = [
                r'@param\s*\{([^}]+)\}',     # @param {Type}
                r'@returns?\s*\{([^}]+)\}',  # @return {Type} or @returns {Type}
                r'@type\s*\{([^}]+)\}',      # @type {Type}
                r'@typedef\s*\{[^}]*\}\s*(\w+)', # @typedef {Object} TypeName
                r'@interface\s+(\w+)',       # @interface InterfaceName
            ]

            for pattern in type_patterns:
                matches = re.findall(pattern, comment_text)
                for match in matches:
                    type_name = match.strip()

                    base_types = self._extract_base_types_from_jsdoc(type_name)

                    for base_type in base_types:
                        if base_type and not self._is_builtin_type_js(base_type):
                            caller_id = f"{self._get_relative_path()}::{caller_name}"
                            resolved = base_type in self.top_level_nodes
                            callee_id = self._get_component_id(base_type) if resolved else base_type

                            type_rel = CallRelationship(
                                caller=caller_id,
                                callee=callee_id,
                                call_line=line_number,
                                is_resolved=resolved
                            )

                            if self._add_relationship(type_rel):
                                pass

        except Exception as e:
            logger.debug(f"Error parsing JSDoc types: {e}")

    def _extract_base_types_from_jsdoc(self, type_str: str) -> list:
        import re
        type_str = type_str.strip()

        base_types = []

        main_type_match = re.match(r'^(\w+)', type_str)
        if main_type_match:
            base_types.append(main_type_match.group(1))

        generic_matches = re.findall(r'<([^<>]+)>', type_str)
        for generic in generic_matches:
            subtypes = re.findall(r'\b(\w+)\b', generic)
            base_types.extend(subtypes)

        if '|' in type_str:
            union_types = type_str.split('|')
            for union_type in union_types:
                clean_type = re.match(r'\b(\w+)\b', union_type.strip())
                if clean_type:
                    base_types.append(clean_type.group(1))

        return base_types

    def _is_builtin_type_js(self, name: str) -> bool:
        """Check if type name is a JavaScript/JSDoc built-in type."""
        builtin_types = {
            # JavaScript primitive types
            "string", "number", "boolean", "object", "undefined", "null", "void", "any",

            # Global JavaScript types
            "Array", "Promise", "Date", "RegExp", "Error", "Map", "Set", "WeakMap", "WeakSet",
            "Function", "Object", "String", "Number", "Boolean", "Symbol", "BigInt",

            "Element", "HTMLElement", "Document", "Window", "Event", "EventTarget", "Node",
            "Response", "Request", "Headers", "URL", "URLSearchParams", "FormData", "Blob", "File",

            # Common JSDoc generic parameters
            "T", "U", "V", "K", "P", "R", "E"
        }
        return name in builtin_types

    def _extract_callee_name(self, call_node) -> Optional[str]:
        if not call_node.children:
            return None

        callee_node = call_node.children[0]

        if callee_node.type == "identifier":
            return self._get_node_text(callee_node)
        elif callee_node.type == "member_expression":
            property_node = self._find_child_by_type(callee_node, "property_identifier")
            if property_node:
                return self._get_node_text(property_node)

            computed_property = self._find_child_by_type(callee_node, "computed_property_name")
            if computed_property:
                for child in computed_property.children:
                    if child.type == "identifier":
                        return self._get_node_text(child)
        elif callee_node.type == "super":
            return "super"
        elif callee_node.type == "this":
            return "this"

        return None

    def _find_child_by_type(self, node, node_type: str):
        """Find first child node of specified type."""
        for child in node.children:
            if child.type == node_type:
                return child
        return None

    def _get_node_text(self, node) -> str:
        start_byte = node.start_byte
        end_byte = node.end_byte
        return self.content.encode("utf8")[start_byte:end_byte].decode("utf8")

    def _find_containing_class_name(self, method_node) -> Optional[str]:
        current = method_node.parent
        while current:
            if current.type == "class_declaration":
                name_node = self._find_child_by_type(current, "identifier")
                if name_node:
                    return self._get_node_text(name_node)
            current = current.parent
        return None

    def _extract_assignment_name(self, node) -> Optional[str]:
        if node.type == "identifier":
            return self._get_node_text(node)
        elif node.type == "member_expression":
            property_node = self._find_child_by_type(node, "property_identifier")
            if property_node:
                return self._get_node_text(property_node)
        return None

def analyze(self) -> None:
    if self.parser is None:
        logger.warning(f"Skipping {self.file_path} - parser initialization failed")
        return

    try:
        tree = self.parser.parse(bytes(self.content, "utf8"))
        root_node = tree.root_node

        logger.debug(f"Parsed AST with root node type: {root_node.type}")

        self._extract_functions(root_node)
        self._extract_call_relationships(root_node)

        logger.debug(
            f"Analysis complete: {len(self.nodes)} nodes, {len(self.call_relationships)} relationships"
        )

    except Exception as e:
        logger.error(f"Error analyzing JavaScript file {self.file_path}: {e}", exc_info=True)

def _get_module_path(self) -> str:
    if self.repo_path:
        try:
            rel_path = os.path.relpath(str(self.file_path), self.repo_path)
        except ValueError:
            rel_path = str(self.file_path)
    else:
        rel_path = str(self.file_path)

    for ext in ['.js', '.ts', '.jsx', '.tsx', '.mjs', '.cjs']:
        if rel_path.endswith(ext):
            rel_path = rel_path[:-len(ext)]
            break
    return rel_path.replace('/', '.').replace('\\', '.')

def _get_relative_path(self) -> str:
    if self.repo_path:
        try:
            return os.path.relpath(str(self.file_path), self.repo_path)
        except ValueError:
            return str(self.file_path)
    else:
        return str(self.file_path)

def _get_component_id(self, name: str, class_name: str = None, is_method: bool = False) -> str:
    relative_path = self._get_relative_path()

    if is_method and class_name:
        return f"{relative_path}::{class_name}.{name}"
    elif class_name and not is_method:
        return f"{relative_path}::{name}"
    else:
        return f"{relative_path}::{name}"

def _find_containing_class(self, node) -> Optional[str]:
    parent = node.parent
    while parent:
        if parent.type in ["class_declaration", "abstract_class_declaration", "interface_declaration"]:
            name_node = self._find_child_by_type(parent, "type_identifier")
            if not name_node:
                name_node = self._find_child_by_type(parent, "identifier")
            if name_node:
                return self._get_node_text(name_node)
        parent = parent.parent
    return None

def _extract_functions(self, node) -> None:
    self._traverse_for_functions(node)
    self.nodes.sort(key=lambda n: n.start_line)

def _traverse_for_functions(self, node) -> None:
    if node.type in ["class_declaration", "abstract_class_declaration", "interface_declaration"]:
        cls = self._extract_class_declaration(node)
        if cls:
            self.nodes.append(cls)
            self.top_level_nodes[cls.name] = cls

            self._extract_methods_from_class(node, cls.name)

    elif node.type == "function_declaration":
        containing_class = self._find_containing_class(node)
        if containing_class is None:
            func = self._extract_function_declaration(node)
            if func and self._should_include_function(func):
                self.nodes.append(func)
                self.top_level_nodes[func.name] = func
    elif node.type == "generator_function_declaration":
        containing_class = self._find_containing_class(node)
        if containing_class is None:
            func = self._extract_function_declaration(node)
            if func and self._should_include_function(func):
                self.nodes.append(func)
                self.top_level_nodes[func.name] = func
    elif node.type == "export_statement":
        func = self._extract_exported_function(node)
        if func and self._should_include_function(func):
            self.nodes.append(func)
            self.top_level_nodes[func.name] = func
    elif node.type == "lexical_declaration":
        containing_class = self._find_containing_class(node)
        if containing_class is None:
            func = self._extract_arrow_function_from_declaration(node)
            if func and self._should_include_function(func):
                self.nodes.append(func)
                self.top_level_nodes[func.name] = func

    for child in node.children:
        self._traverse_for_functions(child)

def _extract_methods_from_class(self, class_node, class_name: str) -> None:
    class_body = self._find_child_by_type(class_node, "class_body")
    if not class_body:
        return

    for child in class_body.children:
        if child.type == "method_definition":
            method_name = self._get_method_name(child)
            if method_name:
                method_node = self._create_method_node(child, method_name, class_name)
                if method_node:
                    if method_name != "constructor":
                        self.nodes.append(method_node)
                    self.top_level_nodes[method_node.name] = method_node
        elif child.type == "field_definition":
            # Handle arrow function properties
            field_name = self._get_field_name(child)
            if field_name and self._is_arrow_function_field(child):
                method_node = self._create_method_node(child, field_name, class_name)
                if method_node:
                    self.nodes.append(method_node)
                    self.top_level_nodes[method_node.name] = method_node

def _get_method_name(self, method_node) -> Optional[str]:
    """Get method name from method_definition node."""
    if method_node.type != "method_definition":
        return None

    for child in method_node.children:
        if child.type == "property_identifier":
            return self._get_node_text(child)
    return None

def _get_field_name(self, field_node) -> Optional[str]:
    """Get field name from field_definition node."""
    if field_node.type != "field_definition":
        return None

    for child in field_node.children:
        if child.type == "property_identifier":
            return self._get_node_text(child)
    return None

def _is_arrow_function_field(self, field_node) -> bool:
    """Check if field_definition contains an arrow function."""
    for child in field_node.children:
        if child.type == "arrow_function":
            return True
    return False

def _extract_exported_function(self, node) -> Optional[Node]:
    """Extract export function or export default function"""
    try:
        func_decl = self._find_child_by_type(node, "function_declaration")
        if func_decl:
            func = self._extract_function_declaration(func_decl)
            if func:
                export_text = self._get_node_text(node)
                if "export default" in export_text and "function (" in export_text:
                    func.name = "default"
            return func
    except Exception as e:
        logger.debug(f"Error extracting exported function: {e}")
    return None

def _should_include_function(self, func: Node) -> bool:
    excluded_names = {}

    if func.name.lower() in excluded_names:
        logger.debug(f"Skipping excluded function: {func.name}")
        return False

    return True

def _extract_parameters(self, node) -> List[str]:
    parameters = []
    params_node = self._find_child_by_type(node, "formal_parameters")
    if params_node:
        for child in params_node.children:
            if child.type == "identifier":
                parameters.append(self._get_node_text(child))
    return parameters

def _extract_call_relationships(self, node) -> None:
    current_top_level = None
    self._traverse_for_calls(node, current_top_level)

def _traverse_for_calls(self, node, current_top_level) -> None:
    if current_top_level:
        self._extract_jsdoc_type_dependencies(node, current_top_level)

    if node.type in ["class_declaration", "abstract_class_declaration", "interface_declaration"]:
        name_node = self._find_child_by_type(node, "type_identifier") or self._find_child_by_type(node, "identifier")
        if name_node:
            current_top_level = self._get_node_text(name_node)

            heritage_node = self._find_child_by_type(node, "class_heritage")
            if heritage_node:
                for child in heritage_node.children:
                    if child.type in ["identifier", "type_identifier"]:
                        base_class = self._get_node_text(child)
                        caller_id = self._get_component_id(current_top_level)
                        resolved = base_class in self.top_level_nodes
                        callee_id = self._get_component_id(base_class) if resolved else base_class
                        inheritance_rel = CallRelationship(
                            caller=caller_id,
                            callee=callee_id,
                            call_line=node.start_point[0] + 1,
                            is_resolved=resolved
                        )
                        self._add_relationship(inheritance_rel)

    elif node.type in ("method_definition", "field_definition"):
        name = self._get_method_name(node) if node.type == "method_definition" else self._get_field_name(node)
        containing_class = self._find_containing_class(node)
        if name and containing_class and f"{containing_class}.{name}" in self.top_level_nodes:
            current_top_level = f"{containing_class}.{name}"

    elif node.type == "function_declaration":
        name_node = self._find_child_by_type(node, "identifier")
        if name_node:
            current_top_level = self._get_node_text(name_node)
    elif node.type == "generator_function_declaration":
        name_node = self._find_child_by_type(node, "identifier")
        if name_node:
            current_top_level = self._get_node_text(name_node)
    elif node.type == "lexical_declaration":
        for child in node.children:
            if child.type == "variable_declarator":
                name_node = self._find_child_by_type(child, "identifier")
                func_node = self._find_child_by_type(child, "arrow_function") or self._find_child_by_type(child, "function_expression")
                if name_node and func_node:
                    current_top_level = self._get_node_text(name_node)

    if node.type == "call_expression" and current_top_level:
        call_info = self._extract_call_from_node(node, current_top_level)
        if call_info:
            self._add_relationship(call_info)

    elif node.type == "await_expression" and current_top_level:
        call_expr = self._find_child_by_type(node, "call_expression")
        if call_expr:
            call_info = self._extract_call_from_node(call_expr, current_top_level)
            if call_info:
                self._add_relationship(call_info)

    elif node.type == "new_expression" and current_top_level:
        constructor_node = self._find_child_by_type(node, "identifier")
        if constructor_node is not None:
            callee_name = self._get_node_text(constructor_node)
            resolved = callee_name in self.top_level_nodes
            call_info = CallRelationship(
                caller=f"{self._get_relative_path()}::{current_top_level}",
                callee=self._get_component_id(callee_name) if resolved else callee_name,
                call_line=node.start_point[0] + 1,
                is_resolved=resolved
            )
            self._add_relationship(call_info)

    for child in node.children:
        self._traverse_for_calls(child, current_top_level)

def _extract_call_from_node(self, node, caller_name: str) -> Optional[CallRelationship]:
    """Extract one relationship from a call_expression node.

    Plain identifier calls resolve against same-file components; member
    calls resolve receiver-first (this/super against the enclosing class,
    new-ed variables against their class). Unresolved callees stay bare
    logical names, never file-prefixed.
    """
    try:
        call_line = node.start_point[0] + 1
        caller_id = f"{self._get_relative_path()}::{caller_name}"
        func_node = node.children[0] if node.children else None
        if func_node is None:
            return None

        def make(callee_name: str, resolved: bool) -> CallRelationship:
            return CallRelationship(
                caller=caller_id,
                callee=self._get_component_id(callee_name) if resolved else callee_name,
                call_line=call_line,
                is_resolved=resolved,
            )

        if func_node.type == "identifier":
            name = self._get_node_text(func_node)
            if not name:
                return None
            return make(name, name in self.top_level_nodes)

        if func_node.type != "member_expression":
            return None

        property_node = func_node.child_by_field_name("property")
        obj = func_node.child_by_field_name("object")
        if property_node is None or property_node.type != "property_identifier" or obj is None:
            return None
        tail = self._get_node_text(property_node)

        if obj.type in ("this", "super"):
            class_name = caller_name.split(".")[0]
            candidates = [] if obj.type == "super" else [class_name]
            class_node = self.top_level_nodes.get(class_name)
            if class_node is not None and class_node.base_classes:
                candidates.extend(class_node.base_classes)
            for candidate in candidates:
                if f"{candidate}.{tail}" in self.top_level_nodes:
                    return make(f"{candidate}.{tail}", True)
            target = candidates[0] if candidates else class_name
            return make(f"{target}.{tail}", False)

        if obj.type == "identifier":
            receiver = self._get_node_text(obj)
            if receiver in self.top_level_nodes or self._receiver_class(node, receiver):
                cls = receiver if receiver in self.top_level_nodes else self._receiver_class(node, receiver)
                return make(f"{cls}.{tail}", f"{cls}.{tail}" in self.top_level_nodes)
            return make(f"{receiver}.{tail}", False)

        if obj.type == "member_expression":
            chain = self._identifier_chain(obj)
            if chain:
                return make(f"{chain}.{tail}", False)

        # Composite or literal receiver: a builtin-prototype method on an
        # unknowable receiver can never resolve to a project component.
        if tail not in JS_TS_PROTOTYPE_METHODS:
            return make(tail, False)
        return None

    except Exception as e:
        logger.debug(f"Error extracting call relationship: {e}")
        return None

def _identifier_chain(self, node) -> Optional[str]:
    """Flatten a member expression into dotted text when it is a pure
    identifier chain; None when any link is computed."""
    parts = []
    current = node
    while current.type == "member_expression":
        property_node = current.child_by_field_name("property")
        if property_node is None or property_node.type != "property_identifier":
            return None
        parts.append(self._get_node_text(property_node))
        current = current.child_by_field_name("object")
        if current is None:
            return None
    if current.type != "identifier":
        return None
    parts.append(self._get_node_text(current))
    return ".".join(reversed(parts))

def _receiver_class(self, call_node, identifier: str) -> Optional[str]:
    """Find the class of a local identifier from a `new X()` initializer
    in an enclosing scope."""
    scope = call_node.parent
    while scope:
        if scope.type in (
            "method_definition", "function_declaration",
            "generator_function_declaration", "arrow_function",
            "function_expression", "program",
        ):
            found = self._find_new_initializer(scope, identifier)
            if found:
                return found
        scope = scope.parent
    return None

def _find_new_initializer(self, scope_node, identifier: str) -> Optional[str]:
    stack = [scope_node]
    while stack:
        current = stack.pop()
        if current.type == "variable_declarator":
            name_node = self._find_child_by_type(current, "identifier")
            if name_node is not None and self._get_node_text(name_node) == identifier:
                new_expr = self._find_child_by_type(current, "new_expression")
                if new_expr is not None:
                    ctor = self._find_child_by_type(new_expr, "identifier")
                    if ctor is not None:
                        return self._get_node_text(ctor)
        stack.extend(current.children)
    return None

def _extract_jsdoc_type_dependencies(self, node, caller_name: str) -> None:
    """Extract type dependencies from JSDoc comments."""
    try:
        if hasattr(node, 'prev_sibling') and node.prev_sibling:
            prev = node.prev_sibling
            if prev.type == "comment":
                comment_text = self._get_node_text(prev)
                self._parse_jsdoc_types(comment_text, caller_name, node.start_point[0] + 1)

        for child in node.children:
            if child.type == "comment":
                comment_text = self._get_node_text(child)
                self._parse_jsdoc_types(comment_text, caller_name, node.start_point[0] + 1)

    except Exception as e:
        logger.debug(f"Error extracting JSDoc dependencies: {e}")

def _parse_jsdoc_types(self, comment_text: str, caller_name: str, line_number: int) -> None:
    """Parse JSDoc comment text and extract type references."""
    import re
    try:
        type_patterns = [
            r'@param\s*\{([^}]+)\}',     # @param {Type}
            r'@returns?\s*\{([^}]+)\}',  # @return {Type} or @returns {Type}
            r'@type\s*\{([^}]+)\}',      # @type {Type}
            r'@typedef\s*\{[^}]*\}\s*(\w+)', # @typedef {Object} TypeName
            r'@interface\s+(\w+)',       # @interface InterfaceName
        ]

        for pattern in type_patterns:
            matches = re.findall(pattern, comment_text)
            for match in matches:
                type_name = match.strip()

                base_types = self._extract_base_types_from_jsdoc(type_name)

                for base_type in base_types:
                    if base_type and not self._is_builtin_type_js(base_type):
                        caller_id = f"{self._get_relative_path()}::{caller_name}"
                        resolved = base_type in self.top_level_nodes
                        callee_id = self._get_component_id(base_type) if resolved else base_type

                        type_rel = CallRelationship(
                            caller=caller_id,
                            callee=callee_id,
                            call_line=line_number,
                            is_resolved=resolved
                        )

                        if self._add_relationship(type_rel):
                            pass

    except Exception as e:
        logger.debug(f"Error parsing JSDoc types: {e}")

def _extract_base_types_from_jsdoc(self, type_str: str) -> list:
    import re
    type_str = type_str.strip()

    base_types = []

    main_type_match = re.match(r'^(\w+)', type_str)
    if main_type_match:
        base_types.append(main_type_match.group(1))

    generic_matches = re.findall(r'<([^<>]+)>', type_str)
    for generic in generic_matches:
        subtypes = re.findall(r'\b(\w+)\b', generic)
        base_types.extend(subtypes)

    if '|' in type_str:
        union_types = type_str.split('|')
        for union_type in union_types:
            clean_type = re.match(r'\b(\w+)\b', union_type.strip())
            if clean_type:
                base_types.append(clean_type.group(1))

    return base_types

def _extract_callee_name(self, call_node) -> Optional[str]:
    if not call_node.children:
        return None

    callee_node = call_node.children[0]

    if callee_node.type == "identifier":
        return self._get_node_text(callee_node)
    elif callee_node.type == "member_expression":
        property_node = self._find_child_by_type(callee_node, "property_identifier")
        if property_node:
            return self._get_node_text(property_node)

        computed_property = self._find_child_by_type(callee_node, "computed_property_name")
        if computed_property:
            for child in computed_property.children:
                if child.type == "identifier":
                    return self._get_node_text(child)
    elif callee_node.type == "super":
        return "super"
    elif callee_node.type == "this":
        return "this"

    return None

def _find_child_by_type(self, node, node_type: str):
    """Find first child node of specified type."""
    for child in node.children:
        if child.type == node_type:
            return child
    return None

def _get_node_text(self, node) -> str:
    start_byte = node.start_byte
    end_byte = node.end_byte
    return self.content.encode("utf8")[start_byte:end_byte].decode("utf8")

def _find_containing_class_name(self, method_node) -> Optional[str]:
    current = method_node.parent
    while current:
        if current.type == "class_declaration":
            name_node = self._find_child_by_type(current, "identifier")
            if name_node:
                return self._get_node_text(name_node)
        current = current.parent
    return None

def _extract_assignment_name(self, node) -> Optional[str]:
    if node.type == "identifier":
        return self._get_node_text(node)
    elif node.type == "member_expression":
        property_node = self._find_child_by_type(node, "property_identifier")
        if property_node:
            return self._get_node_text(property_node)
    return None

def analyze_javascript_file_treesitter(
    file_path: str, content: str, repo_path: str = None
) -> Tuple[List[Node], List[CallRelationship]]:
    """Analyze a JavaScript file using tree-sitter."""
    try:
        logger.debug(f"Tree-sitter JS analysis for {file_path}")
        analyzer = TreeSitterJSAnalyzer(file_path, content, repo_path)
        analyzer.analyze()
        logger.debug(
            f"Found {len(analyzer.nodes)} top-level nodes, {len(analyzer.call_relationships)} calls"
        )
        return analyzer.nodes, analyzer.call_relationships
    except Exception as e:
        logger.error(f"Error in tree-sitter JS analysis for {file_path}: {e}", exc_info=True)
        return [], []

class TreeSitterKotlinAnalyzer:
    def __init__(self, file_path: str, content: str, repo_path: Optional[str] = None):
        self.file_path = Path(file_path)
        self.content = content
        self.repo_path = repo_path or ""
        self.nodes: List[Node] = []
        self.call_relationships: List[CallRelationship] = []
        self._analyze()

    def _get_module_path(self) -> str:
        if self.repo_path:
            try:
                rel_path = os.path.relpath(str(self.file_path), self.repo_path)
            except ValueError:
                rel_path = str(self.file_path)
        else:
            rel_path = str(self.file_path)

        for ext in ['.kt', '.kts']:
            if rel_path.endswith(ext):
                rel_path = rel_path[:-len(ext)]
                break
        return rel_path.replace('/', '.').replace('\\', '.')

    def _get_relative_path(self) -> str:
        """Get relative path from repo root."""
        if self.repo_path:
            try:
                return os.path.relpath(str(self.file_path), self.repo_path)
            except ValueError:
                return str(self.file_path)
        else:
            return str(self.file_path)

    def _get_component_id(self, name: str, parent_class: Optional[str] = None) -> str:
        rel_path = self._get_relative_path()
        if parent_class:
            return f"{rel_path}::{parent_class}.{name}"
        else:
            return f"{rel_path}::{name}"

    def _analyze(self):
        try:
            language_capsule = tree_sitter_kotlin.language()
            kotlin_language = Language(language_capsule)
            parser = Parser(kotlin_language)
            tree = parser.parse(bytes(self.content, "utf8"))
            root = tree.root_node
            lines = self.content.splitlines()

            top_level_nodes = {}

            self._extract_nodes(root, top_level_nodes, lines)
            self._extract_relationships(root, top_level_nodes)
        except Exception as e:
            logger.error(f"Error parsing Kotlin file {self.file_path}: {e}")

    def _extract_nodes(self, node, top_level_nodes, lines):
        node_type = None
        node_name = None

        if node.type == "class_declaration":
            is_interface = any(c.type == "interface" for c in node.children)

            if is_interface:
                node_type = "interface"
            else:
                modifiers = self._get_class_modifiers(node)
                if "abstract" in modifiers:
                    node_type = "abstract class"
                elif "data" in modifiers:
                    node_type = "data class"
                elif "enum" in modifiers:
                    node_type = "enum class"
                elif "annotation" in modifiers:
                    node_type = "annotation class"
                else:
                    node_type = "class"

            name_node = next((c for c in node.children if c.type == "identifier"), None)
            node_name = name_node.text.decode() if name_node else None

        elif node.type == "object_declaration":
            node_type = "object"
            name_node = next((c for c in node.children if c.type == "identifier"), None)
            node_name = name_node.text.decode() if name_node else None

        elif node.type == "function_declaration":
            name_node = next((c for c in node.children if c.type == "identifier"), None)
            if name_node:
                method_name = name_node.text.decode()
                containing_class = self._find_containing_class_name(node)
                if containing_class:
                    node_type = "method"
                    node_name = f"{containing_class}.{method_name}"
                else:
                    node_type = "function"
                    node_name = method_name

        if node_type and node_name:
            component_id = self._get_component_id(node_name)
            relative_path = self._get_relative_path()

            # Extract docstring if present
            docstring = ""
            if node.prev_sibling and hasattr(node.prev_sibling, "type"):
                if node.prev_sibling.type in ("line_comment", "block_comment"):
                    docstring = node.prev_sibling.text.decode().strip()

            # Safely extract code lines
            start_line_idx = node.start_point[0]
            end_line_idx = node.end_point[0] + 1
            code_snippet = "\n".join(lines[start_line_idx:end_line_idx]) if start_line_idx < len(lines) else ""

            node_obj = Node(
                id=component_id,
                name=node_name,
                component_type=node_type,
                file_path=str(self.file_path),
                relative_path=relative_path,
                source_code=code_snippet,
                start_line=node.start_point[0]+1,
                end_line=node.end_point[0]+1,
                has_docstring=bool(docstring),
                docstring=docstring,
                parameters=None,
                node_type=node_type,
                base_classes=None,
                class_name=None,
                display_name=f"{node_type} {node_name}",
                component_id=component_id
            )
            self.nodes.append(node_obj)
            top_level_nodes[node_name] = node_obj

        for child in node.children:
            self._extract_nodes(child, top_level_nodes, lines)

    def _get_class_modifiers(self, class_node) -> set:
        """Extract class modifiers (abstract, data, enum, annotation, etc.)."""
        modifiers = set()
        modifiers_node = next((c for c in class_node.children if c.type == "modifiers"), None)
        if modifiers_node:
            for mod in modifiers_node.children:
                if mod.type in ("class_modifier", "inheritance_modifier", "visibility_modifier"):
                    for inner in mod.children:
                        modifiers.add(inner.type)
        return modifiers

    def _extract_relationships(self, node, top_level_nodes):
        # 1. Inheritance and Interface Implementation via delegation_specifiers
        if node.type == "class_declaration":
            class_name = self._get_identifier_name(node)
            delegation_specifiers = next(
                (c for c in node.children if c.type == "delegation_specifiers"), None
            )
            if delegation_specifiers and class_name:
                for spec in delegation_specifiers.children:
                    if spec.type == "delegation_specifier":
                        for child in spec.children:
                            type_name = None
                            if child.type == "constructor_invocation":
                                user_type = next(
                                    (c for c in child.children if c.type == "user_type"), None
                                )
                                if user_type:
                                    type_name = self._get_type_name(user_type)
                            elif child.type == "user_type":
                                type_name = self._get_type_name(child)

                            if type_name and not self._is_primitive_type(type_name):
                                caller_id = self._get_component_id(class_name)
                                callee_id = self._get_component_id(type_name)
                                self.call_relationships.append(CallRelationship(
                                    caller=caller_id,
                                    callee=callee_id,
                                    call_line=node.start_point[0]+1,
                                    is_resolved=False
                                ))

        # 2. Property Type Use (field types)
        if node.type == "property_declaration":
            containing_class = self._find_containing_class(node, top_level_nodes)
            var_decl = next((c for c in node.children if c.type == "variable_declaration"), None)
            if containing_class and var_decl:
                type_node = next(
                    (c for c in var_decl.children if c.type == "user_type"), None
                )
                if type_node:
                    prop_type_name = self._get_type_name(type_node)
                    if prop_type_name and not self._is_primitive_type(prop_type_name):
                        self.call_relationships.append(CallRelationship(
                            caller=containing_class,
                            callee=prop_type_name,
                            call_line=node.start_point[0]+1,
                            is_resolved=False
                        ))

        # 3. Constructor parameter type use
        if node.type == "class_parameter":
            containing_class_node = node.parent
            while containing_class_node and containing_class_node.type != "class_declaration":
                containing_class_node = containing_class_node.parent
            if containing_class_node:
                class_name = self._get_identifier_name(containing_class_node)
                if class_name and class_name in top_level_nodes:
                    type_node = next(
                        (c for c in node.children if c.type == "user_type"), None
                    )
                    if type_node:
                        param_type = self._get_type_name(type_node)
                        if param_type and not self._is_primitive_type(param_type):
                            caller_id = self._get_component_id(class_name)
                            self.call_relationships.append(CallRelationship(
                                caller=caller_id,
                                callee=param_type,
                                call_line=node.start_point[0]+1,
                                is_resolved=False
                            ))

        # 4. Method Calls / Function invocations
        if node.type == "call_expression":
            caller_id = self._find_containing_method(node) or self._find_containing_class(node, top_level_nodes)

            target_expr = next(
                (c for c in node.children if c.type in ["identifier", "navigation_expression"]), None
            )

            if target_expr and caller_id:
                if target_expr.type == "identifier":
                    callee_name = target_expr.text.decode()
                    if callee_name and callee_name[0].isupper() and not self._is_primitive_type(callee_name):
                        callee_id = self._get_component_id(callee_name)
                        self.call_relationships.append(CallRelationship(
                            caller=caller_id,
                            callee=callee_id,
                            call_line=node.start_point[0]+1,
                            is_resolved=False
                        ))
                    elif callee_name and not self._is_primitive_type(callee_name):
                        self.call_relationships.append(CallRelationship(
                            caller=caller_id,
                            callee=callee_name,
                            call_line=node.start_point[0]+1,
                            is_resolved=False
                        ))

                elif target_expr.type == "navigation_expression":
                    children = list(target_expr.children)
                    object_node = next(
                        (c for c in children if c.type == "identifier"), None
                    )
                    method_node = None
                    identifiers = [c for c in children if c.type == "identifier"]
                    if len(identifiers) >= 2:
                        object_node = identifiers[0]
                        method_node = identifiers[-1]
                    elif len(identifiers) == 1:
                        method_node = identifiers[0]
                        nav_child = next(
                            (c for c in children if c.type == "navigation_expression"), None
                        )
                        if nav_child:
                            object_node = self._get_root_identifier(nav_child)
                        else:
                            object_node = None

                    if object_node and method_node:
                        object_name = object_node.text.decode() if hasattr(object_node, 'text') else str(object_node)
                        method_name = method_node.text.decode()

                        target_type = None
                        if object_name in top_level_nodes:
                            target_type = object_name
                        else:
                            target_type = self._find_variable_type(node, object_name, top_level_nodes)

                        if target_type and not self._is_primitive_type(target_type):
                            callee_id = self._get_component_id(target_type)
                            self.call_relationships.append(CallRelationship(
                                caller=caller_id,
                                callee=callee_id,
                                call_line=node.start_point[0]+1,
                                is_resolved=False
                            ))
                    elif method_node and not object_node:
                        callee_name = method_node.text.decode()
                        self.call_relationships.append(CallRelationship(
                            caller=caller_id,
                            callee=callee_name,
                            call_line=node.start_point[0]+1,
                            is_resolved=False
                        ))

        for child in node.children:
            self._extract_relationships(child, top_level_nodes)

    def _is_primitive_type(self, type_name: str) -> bool:
        """Check if type is a Kotlin primitive or common built-in type."""
        primitives = {
            "Boolean", "Byte", "Char", "Double", "Float", "Int", "Long", "Short",
            "String", "Unit", "Nothing", "Any",
            "List", "Set", "Map", "Collection", "Iterable", "Sequence",
            "MutableList", "MutableSet", "MutableMap", "MutableCollection",
            "Array", "IntArray", "LongArray", "FloatArray", "DoubleArray",
            "BooleanArray", "ByteArray", "CharArray", "ShortArray",
            "Pair", "Triple",
        }
        return type_name in primitives

    def _get_identifier_name(self, node):
        """Get identifier name from a node."""
        name_node = next((c for c in node.children if c.type == "identifier"), None)
        return name_node.text.decode() if name_node else None

    def _get_type_name(self, node) -> Optional[str]:
        """Get the primary type name from a type node, stripping generics."""
        if node.type == "user_type":
            id_node = next((c for c in node.children if c.type == "identifier"), None)
            return id_node.text.decode() if id_node else None
        elif node.type == "nullable_type":
            inner = next((c for c in node.children if c.type == "user_type"), None)
            if inner:
                return self._get_type_name(inner)
        elif node.type == "identifier":
            return node.text.decode()
        return None

    def _get_root_identifier(self, nav_node):
        """Get the root identifier from a chain of navigation_expressions."""
        first_child = nav_node.children[0] if nav_node.children else None
        if first_child:
            if first_child.type == "identifier":
                return first_child
            elif first_child.type == "navigation_expression":
                return self._get_root_identifier(first_child)
        return None

    def _find_containing_class_name(self, node):
        """Walk up to find the containing class/object/interface name."""
        current = node.parent
        while current:
            if current.type in ("class_declaration", "object_declaration"):
                name_node = next((c for c in current.children if c.type == "identifier"), None)
                if name_node:
                    return name_node.text.decode()
            current = current.parent
        return None

    def _find_containing_class(self, node, top_level_nodes):
        """Find the component ID of the containing class."""
        class_name = self._find_containing_class_name(node)
        if class_name and class_name in top_level_nodes:
             return self._get_component_id(class_name)
        return None

    def _find_containing_method(self, node):
        """Find the component ID of the containing function/method."""
        current = node.parent
        while current:
            if current.type == "function_declaration":
                method_name = self._get_identifier_name(current)
                class_name = self._find_containing_class_name(current)
                if method_name:
                    if class_name:
                        return self._get_component_id(f"{class_name}.{method_name}")
                    return self._get_component_id(method_name)
            current = current.parent
        return None

    def _find_variable_type(self, node, variable_name: str, top_level_nodes) -> Optional[str]:
        """
        Try to resolve the type of a variable by searching local declarations,
        function parameters, constructor parameters, and class properties.
        """
        func_node = node.parent
        while func_node and func_node.type != "function_declaration":
            func_node = func_node.parent

        if func_node:
            params_node = next(
                (c for c in func_node.children if c.type == "function_value_parameters"), None
            )
            if params_node:
                for param in params_node.children:
                    if param.type == "parameter":
                        param_name_node = next(
                            (c for c in param.children if c.type == "identifier"), None
                        )
                        if param_name_node and param_name_node.text.decode() == variable_name:
                            type_node = next(
                                (c for c in param.children if c.type in ("user_type", "nullable_type")), None
                            )
                            if type_node:
                                return self._get_type_name(type_node)

            body_node = next(
                (c for c in func_node.children if c.type == "function_body"), None
            )
            if body_node:
                block = next((c for c in body_node.children if c.type == "block"), None)
                if block:
                    result = self._search_variable_declaration(block, variable_name)
                    if result:
                        return result

        class_node = node.parent
        while class_node and class_node.type not in ("class_declaration", "object_declaration"):
            class_node = class_node.parent

        if class_node:
            primary_ctor = next(
                (c for c in class_node.children if c.type == "primary_constructor"), None
            )
            if primary_ctor:
                class_params = next(
                    (c for c in primary_ctor.children if c.type == "class_parameters"), None
                )
                if class_params:
                    for param in class_params.children:
                        if param.type == "class_parameter":
                            param_name = next(
                                (c for c in param.children if c.type == "identifier"), None
                            )
                            if param_name and param_name.text.decode() == variable_name:
                                type_node = next(
                                    (c for c in param.children if c.type in ("user_type", "nullable_type")), None
                                )
                                if type_node:
                                    return self._get_type_name(type_node)

            class_body = next(
                (c for c in class_node.children if c.type in ("class_body", "enum_class_body")), None
            )
            if class_body:
                for body_child in class_body.children:
                    if body_child.type == "property_declaration":
                        var_decl = next(
                            (c for c in body_child.children if c.type == "variable_declaration"), None
                        )
                        if var_decl:
                            prop_name = next(
                                (c for c in var_decl.children if c.type == "identifier"), None
                            )
                            if prop_name and prop_name.text.decode() == variable_name:
                                type_node = next(
                                    (c for c in var_decl.children if c.type in ("user_type", "nullable_type")), None
                                )
                                if type_node:
                                    return self._get_type_name(type_node)

        return None

    def _search_variable_declaration(self, block_node, variable_name: str) -> Optional[str]:
        """Search for a local variable declaration with explicit type annotation in a block."""
        for child in block_node.children:
            if child.type == "property_declaration":
                var_decl = next(
                    (c for c in child.children if c.type == "variable_declaration"), None
                )
                if var_decl:
                    name_node = next(
                        (c for c in var_decl.children if c.type == "identifier"), None
                    )
                    if name_node and name_node.text.decode() == variable_name:
                        type_node = next(
                            (c for c in var_decl.children if c.type in ("user_type", "nullable_type")), None
                        )
                        if type_node:
                            return self._get_type_name(type_node)

                        init_expr = next(
                            (c for c in child.children if c.type == "call_expression"), None
                        )
                        if init_expr:
                            call_id = next(
                                (c for c in init_expr.children if c.type == "identifier"), None
                            )
                            if call_id:
                                inferred = call_id.text.decode()
                                if inferred and inferred[0].isupper():
                                    return inferred

            elif child.type == "block":
                result = self._search_variable_declaration(child, variable_name)
                if result:
                    return result

        return None

def _get_module_path(self) -> str:
    if self.repo_path:
        try:
            rel_path = os.path.relpath(str(self.file_path), self.repo_path)
        except ValueError:
            rel_path = str(self.file_path)
    else:
        rel_path = str(self.file_path)

    for ext in ['.kt', '.kts']:
        if rel_path.endswith(ext):
            rel_path = rel_path[:-len(ext)]
            break
    return rel_path.replace('/', '.').replace('\\', '.')

def _get_relative_path(self) -> str:
    """Get relative path from repo root."""
    if self.repo_path:
        try:
            return os.path.relpath(str(self.file_path), self.repo_path)
        except ValueError:
            return str(self.file_path)
    else:
        return str(self.file_path)

def _get_component_id(self, name: str, parent_class: Optional[str] = None) -> str:
    rel_path = self._get_relative_path()
    if parent_class:
        return f"{rel_path}::{parent_class}.{name}"
    else:
        return f"{rel_path}::{name}"

def _analyze(self):
    try:
        language_capsule = tree_sitter_kotlin.language()
        kotlin_language = Language(language_capsule)
        parser = Parser(kotlin_language)
        tree = parser.parse(bytes(self.content, "utf8"))
        root = tree.root_node
        lines = self.content.splitlines()

        top_level_nodes = {}

        self._extract_nodes(root, top_level_nodes, lines)
        self._extract_relationships(root, top_level_nodes)
    except Exception as e:
        logger.error(f"Error parsing Kotlin file {self.file_path}: {e}")

def _get_class_modifiers(self, class_node) -> set:
    """Extract class modifiers (abstract, data, enum, annotation, etc.)."""
    modifiers = set()
    modifiers_node = next((c for c in class_node.children if c.type == "modifiers"), None)
    if modifiers_node:
        for mod in modifiers_node.children:
            if mod.type in ("class_modifier", "inheritance_modifier", "visibility_modifier"):
                for inner in mod.children:
                    modifiers.add(inner.type)
    return modifiers

def _extract_relationships(self, node, top_level_nodes):
    # 1. Inheritance and Interface Implementation via delegation_specifiers
    if node.type == "class_declaration":
        class_name = self._get_identifier_name(node)
        delegation_specifiers = next(
            (c for c in node.children if c.type == "delegation_specifiers"), None
        )
        if delegation_specifiers and class_name:
            for spec in delegation_specifiers.children:
                if spec.type == "delegation_specifier":
                    for child in spec.children:
                        type_name = None
                        if child.type == "constructor_invocation":
                            user_type = next(
                                (c for c in child.children if c.type == "user_type"), None
                            )
                            if user_type:
                                type_name = self._get_type_name(user_type)
                        elif child.type == "user_type":
                            type_name = self._get_type_name(child)

                        if type_name and not self._is_primitive_type(type_name):
                            caller_id = self._get_component_id(class_name)
                            callee_id = self._get_component_id(type_name)
                            self.call_relationships.append(CallRelationship(
                                caller=caller_id,
                                callee=callee_id,
                                call_line=node.start_point[0]+1,
                                is_resolved=False
                            ))

    # 2. Property Type Use (field types)
    if node.type == "property_declaration":
        containing_class = self._find_containing_class(node, top_level_nodes)
        var_decl = next((c for c in node.children if c.type == "variable_declaration"), None)
        if containing_class and var_decl:
            type_node = next(
                (c for c in var_decl.children if c.type == "user_type"), None
            )
            if type_node:
                prop_type_name = self._get_type_name(type_node)
                if prop_type_name and not self._is_primitive_type(prop_type_name):
                    self.call_relationships.append(CallRelationship(
                        caller=containing_class,
                        callee=prop_type_name,
                        call_line=node.start_point[0]+1,
                        is_resolved=False
                    ))

    # 3. Constructor parameter type use
    if node.type == "class_parameter":
        containing_class_node = node.parent
        while containing_class_node and containing_class_node.type != "class_declaration":
            containing_class_node = containing_class_node.parent
        if containing_class_node:
            class_name = self._get_identifier_name(containing_class_node)
            if class_name and class_name in top_level_nodes:
                type_node = next(
                    (c for c in node.children if c.type == "user_type"), None
                )
                if type_node:
                    param_type = self._get_type_name(type_node)
                    if param_type and not self._is_primitive_type(param_type):
                        caller_id = self._get_component_id(class_name)
                        self.call_relationships.append(CallRelationship(
                            caller=caller_id,
                            callee=param_type,
                            call_line=node.start_point[0]+1,
                            is_resolved=False
                        ))

    # 4. Method Calls / Function invocations
    if node.type == "call_expression":
        caller_id = self._find_containing_method(node) or self._find_containing_class(node, top_level_nodes)

        target_expr = next(
            (c for c in node.children if c.type in ["identifier", "navigation_expression"]), None
        )

        if target_expr and caller_id:
            if target_expr.type == "identifier":
                callee_name = target_expr.text.decode()
                if callee_name and callee_name[0].isupper() and not self._is_primitive_type(callee_name):
                    callee_id = self._get_component_id(callee_name)
                    self.call_relationships.append(CallRelationship(
                        caller=caller_id,
                        callee=callee_id,
                        call_line=node.start_point[0]+1,
                        is_resolved=False
                    ))
                elif callee_name and not self._is_primitive_type(callee_name):
                    self.call_relationships.append(CallRelationship(
                        caller=caller_id,
                        callee=callee_name,
                        call_line=node.start_point[0]+1,
                        is_resolved=False
                    ))

            elif target_expr.type == "navigation_expression":
                children = list(target_expr.children)
                object_node = next(
                    (c for c in children if c.type == "identifier"), None
                )
                method_node = None
                identifiers = [c for c in children if c.type == "identifier"]
                if len(identifiers) >= 2:
                    object_node = identifiers[0]
                    method_node = identifiers[-1]
                elif len(identifiers) == 1:
                    method_node = identifiers[0]
                    nav_child = next(
                        (c for c in children if c.type == "navigation_expression"), None
                    )
                    if nav_child:
                        object_node = self._get_root_identifier(nav_child)
                    else:
                        object_node = None

                if object_node and method_node:
                    object_name = object_node.text.decode() if hasattr(object_node, 'text') else str(object_node)
                    method_name = method_node.text.decode()

                    target_type = None
                    if object_name in top_level_nodes:
                        target_type = object_name
                    else:
                        target_type = self._find_variable_type(node, object_name, top_level_nodes)

                    if target_type and not self._is_primitive_type(target_type):
                        callee_id = self._get_component_id(target_type)
                        self.call_relationships.append(CallRelationship(
                            caller=caller_id,
                            callee=callee_id,
                            call_line=node.start_point[0]+1,
                            is_resolved=False
                        ))
                elif method_node and not object_node:
                    callee_name = method_node.text.decode()
                    self.call_relationships.append(CallRelationship(
                        caller=caller_id,
                        callee=callee_name,
                        call_line=node.start_point[0]+1,
                        is_resolved=False
                    ))

    for child in node.children:
        self._extract_relationships(child, top_level_nodes)

def _get_type_name(self, node) -> Optional[str]:
    """Get the primary type name from a type node, stripping generics."""
    if node.type == "user_type":
        id_node = next((c for c in node.children if c.type == "identifier"), None)
        return id_node.text.decode() if id_node else None
    elif node.type == "nullable_type":
        inner = next((c for c in node.children if c.type == "user_type"), None)
        if inner:
            return self._get_type_name(inner)
    elif node.type == "identifier":
        return node.text.decode()
    return None

def _get_root_identifier(self, nav_node):
    """Get the root identifier from a chain of navigation_expressions."""
    first_child = nav_node.children[0] if nav_node.children else None
    if first_child:
        if first_child.type == "identifier":
            return first_child
        elif first_child.type == "navigation_expression":
            return self._get_root_identifier(first_child)
    return None

def _find_containing_class_name(self, node):
    """Walk up to find the containing class/object/interface name."""
    current = node.parent
    while current:
        if current.type in ("class_declaration", "object_declaration"):
            name_node = next((c for c in current.children if c.type == "identifier"), None)
            if name_node:
                return name_node.text.decode()
        current = current.parent
    return None

def _find_containing_class(self, node, top_level_nodes):
    """Find the component ID of the containing class."""
    class_name = self._find_containing_class_name(node)
    if class_name and class_name in top_level_nodes:
         return self._get_component_id(class_name)
    return None

def _find_containing_method(self, node):
    """Find the component ID of the containing function/method."""
    current = node.parent
    while current:
        if current.type == "function_declaration":
            method_name = self._get_identifier_name(current)
            class_name = self._find_containing_class_name(current)
            if method_name:
                if class_name:
                    return self._get_component_id(f"{class_name}.{method_name}")
                return self._get_component_id(method_name)
        current = current.parent
    return None

def _find_variable_type(self, node, variable_name: str, top_level_nodes) -> Optional[str]:
    """
    Try to resolve the type of a variable by searching local declarations,
    function parameters, constructor parameters, and class properties.
    """
    func_node = node.parent
    while func_node and func_node.type != "function_declaration":
        func_node = func_node.parent

    if func_node:
        params_node = next(
            (c for c in func_node.children if c.type == "function_value_parameters"), None
        )
        if params_node:
            for param in params_node.children:
                if param.type == "parameter":
                    param_name_node = next(
                        (c for c in param.children if c.type == "identifier"), None
                    )
                    if param_name_node and param_name_node.text.decode() == variable_name:
                        type_node = next(
                            (c for c in param.children if c.type in ("user_type", "nullable_type")), None
                        )
                        if type_node:
                            return self._get_type_name(type_node)

        body_node = next(
            (c for c in func_node.children if c.type == "function_body"), None
        )
        if body_node:
            block = next((c for c in body_node.children if c.type == "block"), None)
            if block:
                result = self._search_variable_declaration(block, variable_name)
                if result:
                    return result

    class_node = node.parent
    while class_node and class_node.type not in ("class_declaration", "object_declaration"):
        class_node = class_node.parent

    if class_node:
        primary_ctor = next(
            (c for c in class_node.children if c.type == "primary_constructor"), None
        )
        if primary_ctor:
            class_params = next(
                (c for c in primary_ctor.children if c.type == "class_parameters"), None
            )
            if class_params:
                for param in class_params.children:
                    if param.type == "class_parameter":
                        param_name = next(
                            (c for c in param.children if c.type == "identifier"), None
                        )
                        if param_name and param_name.text.decode() == variable_name:
                            type_node = next(
                                (c for c in param.children if c.type in ("user_type", "nullable_type")), None
                            )
                            if type_node:
                                return self._get_type_name(type_node)

        class_body = next(
            (c for c in class_node.children if c.type in ("class_body", "enum_class_body")), None
        )
        if class_body:
            for body_child in class_body.children:
                if body_child.type == "property_declaration":
                    var_decl = next(
                        (c for c in body_child.children if c.type == "variable_declaration"), None
                    )
                    if var_decl:
                        prop_name = next(
                            (c for c in var_decl.children if c.type == "identifier"), None
                        )
                        if prop_name and prop_name.text.decode() == variable_name:
                            type_node = next(
                                (c for c in var_decl.children if c.type in ("user_type", "nullable_type")), None
                            )
                            if type_node:
                                return self._get_type_name(type_node)

    return None

def _search_variable_declaration(self, block_node, variable_name: str) -> Optional[str]:
    """Search for a local variable declaration with explicit type annotation in a block."""
    for child in block_node.children:
        if child.type == "property_declaration":
            var_decl = next(
                (c for c in child.children if c.type == "variable_declaration"), None
            )
            if var_decl:
                name_node = next(
                    (c for c in var_decl.children if c.type == "identifier"), None
                )
                if name_node and name_node.text.decode() == variable_name:
                    type_node = next(
                        (c for c in var_decl.children if c.type in ("user_type", "nullable_type")), None
                    )
                    if type_node:
                        return self._get_type_name(type_node)

                    init_expr = next(
                        (c for c in child.children if c.type == "call_expression"), None
                    )
                    if init_expr:
                        call_id = next(
                            (c for c in init_expr.children if c.type == "identifier"), None
                        )
                        if call_id:
                            inferred = call_id.text.decode()
                            if inferred and inferred[0].isupper():
                                return inferred

        elif child.type == "block":
            result = self._search_variable_declaration(child, variable_name)
            if result:
                return result

    return None

def analyze_kotlin_file(file_path: str, content: str, repo_path: Optional[str] = None) -> Tuple[List[Node], List[CallRelationship]]:
    analyzer = TreeSitterKotlinAnalyzer(file_path, content, repo_path)
    return analyzer.nodes, analyzer.call_relationships

class NamespaceResolver:
    """Resolves PHP class names to fully qualified names using use statements."""

    def __init__(self):
        self.current_namespace: str = ""
        self.use_map: Dict[str, str] = {}  # alias -> fully_qualified_name

    def register_namespace(self, ns: str):
        """Set the current namespace."""
        self.current_namespace = ns.replace("\\\\", "\\")

    def register_use(self, fqn: str, alias: str = None):
        """Register a use statement with optional alias."""
        fqn = fqn.replace("\\\\", "\\").lstrip("\\")
        alias = alias or fqn.split("\\")[-1]
        self.use_map[alias] = fqn

    def resolve(self, name: str) -> str:
        """Resolve a name to its fully qualified form."""
        if not name:
            return name

        name = name.replace("\\\\", "\\")

        # Already fully qualified
        if name.startswith("\\"):
            return name[1:]

        # Check use map for alias
        if name in self.use_map:
            return self.use_map[name]

        # Check if first part is an alias (for partial qualified names)
        parts = name.split("\\")
        if parts[0] in self.use_map:
            base = self.use_map[parts[0]]
            if len(parts) > 1:
                return f"{base}\\{'\\'.join(parts[1:])}"
            return base

        # Prepend current namespace
        if self.current_namespace:
            return f"{self.current_namespace}\\{name}"

        return name

def __init__(self):
    self.current_namespace: str = ""
    self.use_map: Dict[str, str] = {}  # alias -> fully_qualified_name

def register_namespace(self, ns: str):
